window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"module":"yiliao","prompt":"2岁以下婴幼儿不宜选用臀大肌注射的原因是","options":["臀大肌未发育完善，有损伤坐骨神经的危险","吸收太慢","疼痛明显","易感染"],"answer":0,"explanation":"婴幼儿臀大肌发育不全且坐骨神经位置表浅，宜选臀中肌、臀小肌或股外侧肌注射。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2501","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"静脉注射进针角度为","options":["45°","5°","15°～30°","90°"],"answer":2,"explanation":"静脉注射进针角度一般为15°～30°，皮内注射为5°，肌内注射为90°。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2502","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"皮内注射前臂试验时，针尖斜面应","options":["深达肌层","垂直刺入","斜面朝下","与皮肤平行刺入"],"answer":3,"explanation":"皮内注射使针尖斜面与皮肤平行刺入皮内，形成皮丘。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2503","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"青霉素皮试液每毫升含青霉素","options":["1000U","100U","200～500U","5000U"],"answer":2,"explanation":"青霉素皮试液浓度为每毫升含青霉素200～500U，皮内注射0.1ml。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2504","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"青霉素过敏性休克首选的抢救药物是","options":["盐酸肾上腺素","地塞米松","异丙嗪","多巴胺"],"answer":0,"explanation":"青霉素过敏性休克应立即皮下注射0.1%盐酸肾上腺素0.5～1ml，为首选抢救药。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2505","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"链霉素过敏反应抢救除肾上腺素外还应使用","options":["碳酸氢钠","葡萄糖酸钙","阿托品","地西泮"],"answer":1,"explanation":"链霉素过敏可静脉注射10%葡萄糖酸钙或5%氯化钙，因钙剂可与链霉素络合减轻毒性反应。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2506","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"破伤风抗毒素（TAT）皮试阳性者应","options":["停止一切注射","采用脱敏注射分四次进行","直接全量注射","改用口服药"],"answer":1,"explanation":"TAT皮试阳性者采用脱敏注射法，分4次剂量递增肌内注射，并备好抢救药品。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2507","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"静脉输液的目的不包括","options":["输入药物","纠正酸碱失衡","补充水分和电解质","增加体重"],"answer":2,"explanation":"静脉输液用于补充体液、电解质、营养及输入药物，不以增加体重为目的。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2508","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"急性肺水肿的典型表现是","options":["干咳无痰","咳铁锈色痰","咳脓痰","咳粉红色泡沫痰"],"answer":3,"explanation":"循环负荷过重（急性肺水肿）表现为呼吸困难、咳粉红色泡沫痰，应立即停止输液、端坐位、高流量吸氧并湿化瓶内加乙醇。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2509","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"静脉输液发生空气栓塞时，应立即协助病人取","options":["平卧位","右侧卧位","左侧卧位并头低足高","半坐卧位"],"answer":2,"explanation":"空气栓塞应立即取左侧卧位、头低足高位，使气泡避开肺动脉口。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2510","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"静脉炎的护理措施正确的是","options":["按摩挤压局部","继续原处输液","患肢下垂","停止在患肢输液，抬高患肢并湿热敷"],"answer":3,"explanation":"静脉炎应停止患处输液、抬高患肢、局部湿热敷或理疗，避免按摩。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2511","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发热反应多发生在输液过程中","options":["24小时后","12小时后","数分钟至1小时内","3天后"],"answer":2,"explanation":"输液发热反应多发生于输液后数分钟至1小时内，表现为寒战、发热。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2512","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输血前须双人核对的目的是","options":["防止过敏","防止溶血","防止输错血","防止感染"],"answer":2,"explanation":"输血前双人核对病人信息与血袋信息，防止输错血型造成严重溶血反应。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2513","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"大量输血后易出现","options":["低血钾","高血钙","低血钙（枸橼酸钠中毒）","高血钠"],"answer":2,"explanation":"大量输血时枸橼酸钠与血钙结合致低血钙，表现为手足抽搐，应静脉补充钙剂。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2514","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"溶血反应的最早表现是","options":["黄疸","头部胀痛、四肢麻木、腰背酸痛","少尿","发热寒战"],"answer":1,"explanation":"血管内溶血反应初期表现为头部胀痛、四肢麻木、腰背部剧烈疼痛，随后出现黄疸和血红蛋白尿。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2515","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输血引起溶血反应的根本原因是","options":["输血过快","血型不合","血液污染","输血量过多"],"answer":1,"explanation":"溶血反应多因ABO血型不合导致红细胞破坏，是最严重的输血反应。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2516","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氧疗时湿化瓶内常规加入","options":["生理盐水","灭菌注射用水（湿化液）","75%乙醇","蒸馏水加乙醇"],"answer":1,"explanation":"常规氧疗湿化瓶内加灭菌注射用水或冷开水湿化氧气；急性肺水肿时才加20%～30%乙醇。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2517","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"鼻导管吸氧时氧流量为2L/min，氧浓度约为","options":["29%","20%","40%","50%"],"answer":0,"explanation":"吸氧浓度（%）=21+4×氧流量，2L/min时为21+8=29%。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2518","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"慢性阻塞性肺疾病病人宜采用的氧疗方式","options":["高流量间断吸氧","低流量持续吸氧","纯氧吸入","高流量持续吸氧"],"answer":1,"explanation":"COPD病人呼吸中枢对二氧化碳敏感性降低，应给予低流量（1～2L/min）持续吸氧。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2519","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"用氧安全措施错误的是","options":["氧气筒旁可使用明火","防震、防热","远离火源","氧气筒内不可用尽"],"answer":0,"explanation":"氧气筒应防震、防火、防热、防油，周围严禁烟火，氧气不可用尽以免杂质进入。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2520","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"吸痰时每次吸引时间不超过","options":["3分钟","30秒","1分钟","15秒"],"answer":3,"explanation":"每次吸痰时间不超过15秒，以免造成缺氧。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2521","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"吸痰管插入口腔或鼻腔的深度","options":["插至咽喉部（约10～15cm）后吸引","插入5cm即吸引","插入越深越好","插入后立即吸引"],"answer":0,"explanation":"吸痰管应插至咽喉部再开始吸引，避免损伤黏膜并提高吸痰效果。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2522","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"鼻饲流质饮食每次量不超过","options":["200ml","500ml","100ml","300ml"],"answer":0,"explanation":"鼻饲每次不超过200ml，间隔时间不少于2小时，温度38～40℃。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2523","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"鼻饲液温度适宜的是","options":["45～50℃","20℃","38～41℃","室温"],"answer":2,"explanation":"鼻饲液温度以38～41℃为宜，过冷过热均刺激胃肠道。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2524","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"长期鼻饲者应每日进行","options":["膀胱冲洗","蒸汽吸入","雾化吸入","口腔护理"],"answer":3,"explanation":"长期鼻饲者每日口腔护理2次，防止口腔感染，并定期更换胃管。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2525","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为女病人导尿时，导尿管插入尿道的深度为","options":["10～12cm","7～9cm","2～3cm","4～6cm"],"answer":3,"explanation":"女病人尿道长约3～5cm，导尿时插入4～6cm见尿后再进1cm。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2526","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为男病人导尿时，导尿管插入深度为","options":["4～6cm","10～12cm","20～22cm","15～17cm"],"answer":2,"explanation":"男病人尿道长约18～20cm，导尿时插入20～22cm见尿后再进1～2cm。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2527","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"留置导尿管的病人，为防止感染应","options":["引流管高于膀胱","每周更换尿管即可","每日清洁尿道口，保持引流通畅","尿袋随时可高于膀胱"],"answer":2,"explanation":"留置导尿应每日清洁消毒尿道口，引流管和尿袋低于膀胱，防止逆行感染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2528","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为膀胱高度充盈的病人导尿首次放尿不应超过","options":["1000ml","500ml","200ml","1500ml"],"answer":0,"explanation":"一次放尿不超过1000ml，防止膀胱内压骤降引起虚脱或膀胱出血。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2529","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"大量不保留灌肠时，灌肠液液面距肛门的高度为","options":["40～60cm","20cm","80cm","100cm"],"answer":0,"explanation":"大量不保留灌肠液面距肛门40～60cm，温度39～41℃，插入肛门7～10cm。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2530","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肝性脑病病人禁用的灌肠液是","options":["肥皂水","生理盐水","温开水","乳果糖溶液"],"answer":0,"explanation":"肥皂水为碱性，促进氨吸收，加重肝性脑病，应选用生理盐水或弱酸性溶液灌肠。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2531","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"降温灌肠时灌肠液的温度为","options":["20℃以下","39～41℃","37℃","28～32℃"],"answer":3,"explanation":"降温灌肠用28～32℃等渗盐水，中暑病人用4℃等渗盐水。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2532","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"冷疗减轻疼痛的机制是","options":["加速致痛物质排出","促进血液循环","减轻组织充血","降低神经末梢敏感性"],"answer":3,"explanation":"冷疗使神经末梢敏感性降低而减轻疼痛；热疗降低痛觉神经兴奋性并促进炎症消散。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2533","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"乙醇擦浴的浓度为","options":["50%","25%～35%","75%","95%"],"answer":1,"explanation":"乙醇擦浴用25%～35%乙醇，温度约30℃，以离心方向进行，禁擦胸前区、腹部、后颈、足底。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2534","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"乙醇擦浴禁擦足底的原因是","options":["引起疼痛","引起冻伤","可引起反射性心率减慢和腹泻","影响散热"],"answer":2,"explanation":"足底对冷敏感，冷刺激可引起反射性冠状动脉收缩和腹泻。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2535","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"热水袋使用时水温为","options":["60～70℃","40℃","80℃","90℃"],"answer":0,"explanation":"成人热水袋水温60～70℃，婴幼儿、老年人、末梢循环差者不超过50℃，外加布套。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2536","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"压疮好发部位不包括","options":["腹部脂肪丰厚处","枕部","骨隆突处","足跟"],"answer":2,"explanation":"压疮好发于骨隆突处等长期受压部位，腹部脂肪丰厚处不易发生。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2537","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"压疮淤血红润期的护理重点是","options":["清创换药","去除危险因素，避免压疮继续发展","外科手术","应用抗生素"],"answer":1,"explanation":"淤血红润期应增加翻身次数、避免受压、改善循环，防止发展至更深分期。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2538","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"预防压疮最有效的措施是","options":["按摩骨突处","定时翻身，避免局部长期受压","使用气圈","保持皮肤干燥"],"answer":1,"explanation":"定时翻身、解除局部压力是预防压疮最有效的措施。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2539","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医院感染是指","options":["出院后立即发生的感染均不算","入院时已存在的感染","入院24小时内的感染","病人在入院48小时后发生的感染"],"answer":3,"explanation":"入院48小时后发生的感染且入院时不存在或处于潜伏期者为医院感染。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2540","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"属于医院感染的是","options":["新生儿经产道获得的感染","入院时已存在的阑尾炎","入院后24小时内的原有感染复发","术后伤口感染"],"answer":3,"explanation":"术后伤口感染属于医院感染；入院时已存在或潜伏期内的感染不属于。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2541","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"紫外线消毒的有效距离和时间是","options":["3米内15分钟","5米内10分钟","1米内5分钟","2米内照射30分钟以上"],"answer":3,"explanation":"紫外线灯管消毒有效距离2米内，照射时间30分钟以上。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2542","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"紫外线灯管使用中应每周用","options":["干布擦拭","清水冲洗","75%乙醇棉球擦拭灯管","消毒液浸泡"],"answer":2,"explanation":"紫外线灯管每周用75%～95%乙醇棉球擦拭一次，保持清洁以维持杀菌效果。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2543","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"耐高温、耐湿物品首选的灭菌方法是","options":["紫外线照射","压力蒸汽灭菌法","环氧乙烷灭菌","过氧乙酸浸泡"],"answer":1,"explanation":"压力蒸汽灭菌法杀菌力强、效果好，是耐高温耐湿物品的首选灭菌方法。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2544","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"化学消毒剂戊二醛浸泡灭菌器械的时间为","options":["10小时以上","30分钟","2小时","1小时"],"answer":0,"explanation":"2%戊二醛浸泡灭菌需10小时以上，消毒需20～45分钟。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2545","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"穿脱隔离衣的正确顺序是","options":["穿：先穿袖后系领；脱：先解领后解袖","穿：先系领后穿袖","脱：先脱袖后解领","随意顺序"],"answer":0,"explanation":"穿隔离衣先穿两袖再系领口；脱时先解领口再解袖口，避免污染。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2546","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"严密隔离适用于","options":["水痘","麻疹","霍乱","流行性感冒"],"answer":2,"explanation":"霍乱等传染性强、死亡率高的疾病需严密隔离；麻疹、水痘为呼吸道隔离。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2547","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心跳呼吸骤停时胸外按压与人工呼吸的比例（单人）为","options":["15:2","30:2","5:1","10:2"],"answer":1,"explanation":"单人及双人CPR按压与吹气比例均为30:2。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2548","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"胸外心脏按压的部位是","options":["左胸部","心前区","胸骨上段","胸骨中下1/3交界处"],"answer":3,"explanation":"成人胸外按压部位为胸骨中下1/3交界处（两乳头连线中点），深度5～6cm，频率100～120次/分。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2549","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心肺复苏时判断呼吸及脉搏的时间不应超过","options":["5秒","30秒","1分钟","10秒"],"answer":3,"explanation":"判断颈动脉搏动与呼吸应在10秒内完成，以免延误抢救。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2550","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"海姆立克急救法用于","options":["休克","心搏骤停","溺水","气道异物梗阻"],"answer":3,"explanation":"海姆立克手法通过冲击腹部产生气流排出气道异物，用于气道梗阻。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2551","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"单人搬运病人时，正确的方法是","options":["两人抬四肢","拖行","将病人抱起，使其双臂环抱搬运者颈部","用床单拖拽"],"answer":2,"explanation":"单人搬运宜采用抱持法，病人双臂环抱搬运者颈后，稳妥移动。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2552","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"三人平托搬运脊柱损伤病人的正确方法是","options":["一人抱起","保持脊柱轴线位，平托放于硬板担架","两人抬肩抬腿","背负搬运"],"answer":1,"explanation":"脊柱损伤搬运应保持脊柱轴线一致，三人平托置于硬板担架，防止脊髓损伤。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2553","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"轮椅运送病人时，正确的做法是","options":["病人自行上下","闸制动后再让病人上下","下坡时倒行无需注意","快速推行"],"answer":1,"explanation":"轮椅使用应先闸制动，协助病人安全转移；下坡应减速、病人头朝后。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2554","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病人出院时的床单位处理不包括","options":["立即铺备用床","撤去污被服","床垫、枕芯日光暴晒","病室通风"],"answer":0,"explanation":"出院处理先消毒床单位，再铺备用床，不能先铺床后消毒。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2555","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"特级护理适用于","options":["择期手术前病人","病情稳定者","康复期病人","病情危重、随时需要抢救的病人"],"answer":3,"explanation":"特级护理用于病情危重、需随时观察抢救的病人，专人24小时护理。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2556","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"一级护理病人巡视频率为","options":["每2小时一次","每小时一次","每4小时一次","每30分钟一次"],"answer":1,"explanation":"一级护理每小时巡视一次，二级护理每2小时，三级护理每3小时。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2557","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"抢救物品管理的“五定”不包括","options":["定人保管","定点安置","定数量品种","定期使用"],"answer":2,"explanation":"五定为：定数量品种、定点安置、定人保管、定期消毒灭菌、定期检查维修，无“定期使用”。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2558","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医嘱“st”表示","options":["立即执行，限用一次","每小时一次","必要时","长期有效"],"answer":0,"explanation":"st为立即执行，限用一次；sos为必要时，qod为隔日一次。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2559","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"口头医嘱的处理方法是","options":["直接执行不记录","护士复述确认后执行，抢救后6小时内补记","拒绝执行","让家属签字"],"answer":1,"explanation":"抢救中执行口头医嘱须复述确认，用后保留安瓿，抢救结束后6小时内补记。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2560","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病区交班内容不包括","options":["手术病人","新入病人","危重病人","病人的私人隐私信息"],"answer":3,"explanation":"交班重点为新入、危重、手术、病情变化病人，不涉及无关隐私信息。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2561","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"长期备用医嘱的缩写是","options":["prn","sos","st","qid"],"answer":0,"explanation":"prn为长期备用医嘱，sos为临时备用医嘱（12小时内有效）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2562","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"给药时间“ac”表示","options":["晨起","饭后","睡前","饭前"],"answer":3,"explanation":"ac为饭前，pc为饭后，hs为睡前，qm为每晨。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2563","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"服用强心苷类药物前应先测量","options":["心率（脉搏）","血压","呼吸","体温"],"answer":0,"explanation":"服用洋地黄类药物前测心率，低于60次/分应暂停给药并报告医生。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2564","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"雾化吸入的目的不包括","options":["湿化气道","稀释痰液","治疗呼吸道感染","降低血糖"],"answer":0,"explanation":"雾化吸入用于湿化气道、稀释痰液、治疗呼吸道疾病，与血糖无关。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2565","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"超声雾化吸入时，水槽内水温不得超过","options":["50℃","30℃","60℃","70℃"],"answer":0,"explanation":"超声雾化水槽水温超过50℃应停机换水，以免损坏机器和影响药效。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2566","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氧气雾化吸入时，氧流量一般为","options":["2～4L/min","1～2L/min","6～8L/min","10L/min"],"answer":2,"explanation":"氧气雾化吸入氧流量6～8L/min，使药液形成雾状。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2567","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"疼痛病人应用止痛药的原则是","options":["疼痛时才给强效药","一律肌注","按阶梯给药，尽量口服","大剂量长期使用"],"answer":2,"explanation":"癌痛三阶梯止痛原则：口服给药、按阶梯给药、按时给药、个体化、注意细节。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2568","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临终病人心理反应的五个阶段依次为","options":["否认期、协议期、愤怒期、忧郁期、接受期","愤怒期、否认期、接受期、协议期、忧郁期","接受期、否认期、愤怒期、协议期、忧郁期","否认期、愤怒期、协议期、忧郁期、接受期"],"answer":3,"explanation":"库伯勒·罗斯提出临终心理五期：否认、愤怒、协议（讨价还价）、忧郁、接受。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2569","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"尸体护理时，头部应垫枕的目的是","options":["防止口腔张开","保持体位","防止面部淤血变色","便于辨认"],"answer":2,"explanation":"尸体护理头下垫枕可防止面部淤血变色，维持良好外观。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2570","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"尸体护理时，尸体识别卡应放置三处，不包括","options":["停尸房登记处","尸体手腕部","尸体腰部","尸屉外"],"answer":3,"explanation":"尸体识别卡分别放于手腕、腰部和尸屉外，无停尸房登记处一说。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2571","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病室适宜的温度为","options":["15～18℃","10～15℃","25～30℃","18～22℃"],"answer":3,"explanation":"一般病室温度18～22℃，新生儿及手术室为22～24℃，湿度50%～60%。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2572","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病室湿度过低时，病人可出现","options":["食欲下降","胸闷、憋气","肌肉酸痛","口干舌燥、咽痛"],"answer":3,"explanation":"湿度过低空气干燥，引起口干舌燥、咽痛；过高则感胸闷、憋气。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2573","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"铺备用床的目的是","options":["准备接收新病人","供麻醉术后病人使用","供病人休息","保护被褥"],"answer":0,"explanation":"备用床为接收新病人准备；麻醉床为术后病人准备，可防止污染床单位。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2574","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"麻醉床铺橡胶单、中单的目的是","options":["便于搬运","增加舒适","保暖","防止呕吐物、血液等污染床单位"],"answer":3,"explanation":"麻醉床铺橡胶单中单用于承接术后呕吐物、渗血渗液，保护床单位。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2575","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人翻身时，两人操作的正确方法是","options":["一人拖拽","两人分别扶托病人肩部和腰腿部，协调用力","仅移动上半身","先抬头部"],"answer":1,"explanation":"两人翻身应分段托扶肩背和腰臀腿部，保持脊柱平直，协调用力。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2576","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"协助病人翻身侧卧时，两膝间应","options":["交叉","并拢","伸直","垫软枕"],"answer":3,"explanation":"侧卧位时两膝间垫软枕，上腿弯曲下腿伸直，保持舒适稳定。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2577","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"半坐卧位适用于","options":["腹部手术后病人","休克病人","昏迷病人","脊柱损伤病人"],"answer":0,"explanation":"半坐卧位利于腹腔引流、减轻切口张力，适用于腹部术后及心肺疾病病人。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2578","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"休克病人宜采取的体位是","options":["中凹卧位（头胸10～20°，下肢20～30°）","平卧位","侧卧位","头低足高位"],"answer":0,"explanation":"休克病人取中凹卧位，增加回心血量并改善脑部血流。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2579","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"颅内压增高病人宜取","options":["中凹卧位","头低足高位","头高足低位","俯卧位"],"answer":2,"explanation":"头高足低位可降低颅内压，适用于颅脑术后及颅内压增高病人。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2580","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"保护具使用的原则是","options":["长期使用","知情同意、短期使用、随病情变化调整","惩罚性使用","随意使用"],"answer":1,"explanation":"保护具须取得家属知情同意，短期使用并定时松解，观察血运。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2581","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"约束带使用时，应观察的重点是","options":["局部血液循环","体温","血压","饮食"],"answer":0,"explanation":"使用约束带应每15～30分钟观察局部血运，每2小时松解一次。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2582","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"口腔护理的目的不包括","options":["清除口臭","预防感染","增进食欲","降低体温"],"answer":0,"explanation":"口腔护理用于保持口腔清洁、预防感染、观察口腔变化，不能降低体温。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2583","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为昏迷病人进行口腔护理时，应特别注意","options":["用力擦拭","棉球不可过湿，防止误吸","使用金属镊子","让病人漱口"],"answer":1,"explanation":"昏迷病人口腔护理棉球不可过湿，禁止漱口，防止误吸窒息。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2584","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"长期使用抗生素的病人易发生","options":["真菌感染","细菌性肺炎","病毒性感冒","寄生虫感染"],"answer":0,"explanation":"长期广谱抗生素抑制正常菌群，易致白色念珠菌等真菌二重感染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2585","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"口腔pH偏碱性时，宜选用","options":["0.9%氯化钠溶液","2%～3%硼酸溶液","1%～3%过氧化氢溶液","朵贝尔溶液"],"answer":0,"explanation":"pH偏碱性时选用硼酸溶液；偏酸性时用过氧化氢或朵贝尔液。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2586","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"晨间护理的时间一般在","options":["晚间","中午","清晨诊疗护理前","任意时间"],"answer":2,"explanation":"晨间护理于清晨诊疗护理前进行，包括洗漱、翻身、皮肤护理等。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2587","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"晚间护理的目的是","options":["帮助病人入睡","测量生命体征","采集标本","准备手术"],"answer":0,"explanation":"晚间护理创造安静环境，协助洗漱、调暗灯光，帮助病人入睡。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2588","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"采集静脉血标本时，正确的做法是","options":["从输液同侧肢体采血","先输液后采血","根据检验目的选择试管并按规定量采血","采血后剧烈摇动试管"],"answer":2,"explanation":"采血应避开输液侧肢体，按检验目的选试管，全血标本轻摇混匀防凝固。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2589","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"采集全血标本后应","options":["静置2小时","立即轻轻摇匀，防止凝血","加入防腐剂","冷藏后摇匀"],"answer":1,"explanation":"全血标本采后立即轻摇使抗凝剂与血液混匀，防止凝血。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2590","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"留取尿常规标本的正确时间是","options":["任意时间","晨起第一次尿","餐后2小时","睡前"],"answer":1,"explanation":"晨尿浓缩、不受饮食影响，检查结果准确，宜留晨起第一次尿约100ml。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2591","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"采集粪便寄生虫卵标本时，应","options":["混入尿液","取粪便表面任意部分","整块送检","取不同部位带黏液或脓血部分"],"answer":3,"explanation":"寄生虫卵检查应在粪便不同部位取带黏液脓血部分5～10g送检。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2592","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"阿米巴痢疾病人留取粪便标本时，应","options":["冷藏后送检","便盆加温至接近体温后立即送检","加入防腐剂","干燥后送检"],"answer":1,"explanation":"阿米巴原虫在低温下失去活动力，标本便盆需加温并立即送检。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2593","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"采集痰培养标本时，正确的做法是","options":["清晨漱口后深咳出气管深部痰液","留取口水","餐后立即留取","混入鼻涕"],"answer":0,"explanation":"痰培养应于清晨漱口后深咳留取气管深部痰液，防止口腔杂菌污染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2594","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为休克病人留置导尿的主要目的是","options":["监测每小时尿量，判断肾功能","预防感染","减轻痛苦","采集标本"],"answer":0,"explanation":"休克病人留置导尿监测每小时尿量，作为补液和病情判断的重要指标。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2595","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"膀胱冲洗的目的不包括","options":["治疗膀胱疾病","预防感染","保持引流通畅","增加尿量"],"answer":2,"explanation":"膀胱冲洗用于保持通畅、预防感染、治疗膀胱疾病，不能直接增加尿量。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2596","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"冷敷治疗扭伤早期的作用是","options":["促进淤血吸收","减轻局部充血、出血和疼痛","增加渗出","升高局部温度"],"answer":1,"explanation":"扭伤24小时内冷敷使血管收缩，减轻充血出血和疼痛；48小时后热敷促进吸收。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2597","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"热疗的禁忌证不包括","options":["面部危险三角区感染","软组织扭伤48小时内","出血性疾病","慢性腰痛"],"answer":1,"explanation":"慢性腰痛可热疗促进循环；扭伤早期、面部三角区感染、出血倾向均为热疗禁忌。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2598","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"面部危险三角区感染禁用热疗的原因是","options":["易致面部肿胀","易致颅内感染","影响呼吸","引起过敏"],"answer":1,"explanation":"三角区血管与颅内相通，热疗使细菌入颅，引起颅内感染。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2599","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"热水坐浴的水温为","options":["室温","30℃","50℃以上","40～45℃"],"answer":3,"explanation":"热水坐浴水温40～45℃，坐浴时间15～20分钟，用于会阴、肛门疾病。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2600","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行乙醇拭浴时，出现寒战、面色苍白应","options":["加大乙醇浓度","继续擦浴","加快速度","立即停止擦浴，注意保暖"],"answer":3,"explanation":"擦浴中出现寒战、面色苍白、脉搏异常应立即停止并保暖，防止虚脱。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2601","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"鼻饲前应确认胃管在胃内的方法不包括","options":["听气过水声","回抽胃液","让病人说话","观察有无呛咳"],"answer":2,"explanation":"确认胃管在胃内的方法：回抽胃液、听气过水声、观察气泡，不能让病人说话判断。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2602","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"更换鼻饲胃管的时间为","options":["每2周更换","每日更换","每月更换","每周更换一次"],"answer":3,"explanation":"普通胃管每周更换一次，硅胶胃管每月更换一次，晚间末次喂食后拔出，晨起插入。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2603","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输液中茂菲滴管液面过低时，正确处理是","options":["拔针重输","更换输液器","捏紧滴管上端，挤入适量液体","调高滴管"],"answer":2,"explanation":"滴管液面过低可捏紧上端导管挤压滴管，使液面升至1/3～1/2处。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2604","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输液速度的调节依据不包括","options":["药物性质","年龄","病情","病人的体重"],"answer":3,"explanation":"输液速度依据年龄、病情、药物性质调节，体重不是常规依据。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2605","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心功能不全病人输液速度应","options":["宜快","宜慢，20～30滴/分","正常","先快后慢"],"answer":1,"explanation":"心功能不全者输液宜慢，防止加重心脏负荷诱发肺水肿。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2606","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"静脉输血前，血制品在室温下放置时间不超过","options":["1小时","2小时","30分钟","5分钟"],"answer":2,"explanation":"血液制品取回后应在30分钟内输注，室温放置不超过30分钟。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2607","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输血开始时应","options":["先慢速观察15分钟无反应再调至正常速度","快速输入","直接全速输入","间断输入"],"answer":0,"explanation":"输血开始15分钟内慢速观察有无反应，无异常再调至正常滴速。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2608","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"PICC导管维护时冲管液一般选用","options":["生理盐水10ml以上","蒸馏水","5%葡萄糖","抗生素溶液"],"answer":0,"explanation":"PICC维护用10ml以上生理盐水脉冲式冲管，防止堵管。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2609","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"PICC置管后应观察的内容不包括","options":["导管外露长度","手臂有无肿胀","穿刺点有无渗血","病人的鞋码"],"answer":2,"explanation":"PICC观察穿刺点、肢体肿胀、导管外露长度等，与鞋码无关。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2610","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"化疗药物外渗时，正确的处理是","options":["按摩","热敷","继续输入","立即停止输液并回抽，局部冷敷"],"answer":3,"explanation":"化疗药外渗应立即停止输注、回抽药液、局部冷敷（除个别药物外），报告医生。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2611","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输液泵报警常见原因不包括","options":["气泡","药液将尽","输液管堵塞","病人饥饿"],"answer":2,"explanation":"输液泵报警由堵塞、气泡、药液将尽等引起，与饥饿无关。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2612","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为气管切开病人吸痰时，正确的顺序是","options":["随意顺序","先吸口鼻","先吸气管套管内，再吸口鼻部","先吸鼻腔后吸套管"],"answer":2,"explanation":"气管切开吸痰先吸套管内痰液，再吸口鼻，防止污染气道。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2613","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"气管切开病人内套管消毒的方法是","options":["酒精灯烧灼","煮沸或浸泡消毒后清水冲净","直接使用","高压蒸汽灭菌全部套管"],"answer":1,"explanation":"气管内套管可煮沸或浸泡消毒，外套管不必每日高压灭菌。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2614","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"气切病人吸氧时，宜使用","options":["气切面罩或头罩","鼻导管","鼻塞","普通面罩"],"answer":0,"explanation":"气管切开病人经套管吸氧，宜用气切面罩，不能经鼻导管给氧。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2615","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为卧床病人更换床单时，正确的做法是","options":["快速掀开全部被褥","动作轻稳，注意保暖，避免过多暴露","不考虑病人感受","先撤枕头"],"answer":1,"explanation":"更换床单应动作轻稳、注意保暖遮挡，避免过多暴露病人。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2616","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"协助病人由床向平车移动时，平车与床的位置应","options":["随意摆放","呈直角","平齐，头端朝床头方向","头端朝床尾"],"answer":2,"explanation":"平车与床平行紧靠，搬运时保持病人头部在先，防止损伤。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2617","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"使用平车运送输液病人时，应注意","options":["拔除输液","保持输液通畅，防止针头脱出","夹闭输液管","加快滴速"],"answer":1,"explanation":"平车搬运输液病人应保持输液通畅，防止针头移位脱落。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2618","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人测量体温时，发现体温与病情不符应","options":["直接记录","重新测量并核对","让家属复测","忽略"],"answer":1,"explanation":"体温与病情不符应重新测量核对，必要时测肛温对照。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2619","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"测量肛温时，润滑肛表插入肛门的深度为","options":["7cm","1cm","5～6cm","3～4cm"],"answer":3,"explanation":"肛温测量润滑后插入肛门3～4cm，测量3分钟。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2620","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脉搏短绌的病人测量方法为","options":["单人测1分钟脉率","两人同时测心率与脉率，测1分钟","测30秒乘2","只测心率"],"answer":1,"explanation":"脉搏短绌需两人同时测量心率与脉率各1分钟，以心率记录。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2621","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"呼吸过缓是指成人呼吸频率低于","options":["12次/分","16次/分","10次/分","8次/分"],"answer":0,"explanation":"成人呼吸频率低于12次/分为呼吸过缓，高于24次/分为呼吸过速。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2622","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"潮式呼吸的特点是","options":["呼吸浅快","呼吸深大规则","呼吸由浅慢逐渐深快再变浅慢，暂停后周而复始","呼吸与暂停交替无规律"],"answer":2,"explanation":"潮式（陈-施）呼吸呈周期性由浅慢到深快再变浅慢，随后暂停。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2623","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"库斯莫尔呼吸常见于","options":["肺气肿","支气管哮喘","糖尿病酮症酸中毒","胸腔积液"],"answer":2,"explanation":"代谢性酸中毒时出现深大规则的库斯莫尔呼吸，常见于糖尿病酮症酸中毒。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2624","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"三凹征是指","options":["胸骨上窝、锁骨上窝、肋间隙凹陷","鼻翼、口唇、指端发绀","颈静脉、肝颈静脉、下肢水肿","眼窝、腋窝、腹股沟凹陷"],"answer":0,"explanation":"三凹征为吸气性呼吸困难的典型体征，见于喉头水肿、气管异物等上呼吸道梗阻。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2625","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行鼻导管给氧时，插入深度为","options":["5cm","鼻尖至耳垂的1/3","鼻尖至耳垂全长","鼻尖至耳垂的2/3"],"answer":3,"explanation":"单侧鼻导管给氧插入长度为鼻尖至耳垂的2/3，约10～15cm。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2626","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氧气筒内氧气不可用尽的原因是","options":["节约成本","防止灰尘杂质进入筒内引起爆炸","保持压力恒定","防止漏气"],"answer":1,"explanation":"氧气用尽后杂质进入筒内，再次充氧时可能引起爆炸，应保留0.5MPa余压。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2627","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氧气表上的减压器作用是","options":["过滤氧气","增加氧气流量","将筒内高压氧气降至适宜压力","加热氧气"],"answer":2,"explanation":"减压器将氧气筒内高压降至0.2～0.3MPa便于使用。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2628","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人吸痰前应","options":["先深插后开机","直接插入吸引","先调节负压，试吸通畅后再插入","关闭负压吸引"],"answer":2,"explanation":"吸痰前调节负压（成人40～53.3kPa），试吸通畅后再插入吸引。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2629","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为气管插管病人吸痰时，正确的做法是","options":["不给氧","吸痰中给氧","吸痰前后给予高浓度氧气吸入","先吸痰后给氧"],"answer":2,"explanation":"吸痰前后给予高浓度氧2～3分钟，防止低氧血症。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2630","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行心肺复苏时，按压有效的指征不包括","options":["自主呼吸恢复","面色转红","可触及大动脉搏动","瞳孔散大"],"answer":3,"explanation":"按压有效表现为面色转红、大动脉搏动、瞳孔缩小、自主呼吸恢复，瞳孔散大为无效表现。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2631","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"复苏后病人体位宜取","options":["侧卧位","头低足高位","仰卧位，头部略抬高","俯卧位"],"answer":2,"explanation":"复苏后宜仰卧位、头部略抬高，利于脑部血液回流。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2632","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为危重病人眼睑不能闭合者，应","options":["不予处理","滴入抗生素","用生理盐水冲洗","涂眼药膏并覆盖纱布"],"answer":3,"explanation":"眼睑不能闭合者涂眼膏并覆盖纱布，保护角膜防止干燥感染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2633","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"危重病人护理记录书写要求不包括","options":["完整","客观准确","及时","记录主观猜测"],"answer":3,"explanation":"护理记录应客观、及时、完整、规范，不得主观猜测。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2634","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为昏迷病人翻身时，应注意","options":["保持呼吸道通畅，防止误吸","先喂水","抬高头部","快速翻身"],"answer":0,"explanation":"昏迷病人翻身应保持呼吸道通畅，防止舌后坠和误吸。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2635","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为长期卧床病人进行皮肤护理的目的是","options":["预防压疮","促进消化","增加体重","改善睡眠"],"answer":0,"explanation":"长期卧床皮肤护理重点是保持清洁干燥、促进循环，预防压疮。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2636","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行晨间护理时，发现皮肤发红应","options":["增加翻身次数，避免局部受压","用力按摩","热敷","涂酒精"],"answer":0,"explanation":"皮肤发红为压疮早期表现，应增加翻身、避免受压，不宜用力按摩。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2637","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人测量血压时，发现血压听不清应","options":["立即重测","驱尽袖带气体，间隔片刻重测","换侧肢体","记录为0"],"answer":1,"explanation":"血压听不清应驱尽袖带内气体，汞柱降至零，间隔1～2分钟再测。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2638","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为偏瘫病人测量血压时，应选择","options":["下肢","患侧上肢","双上肢","健侧上肢"],"answer":3,"explanation":"偏瘫病人应在健侧测量，患侧循环差，结果不准确。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2639","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行静脉输液时，发现局部肿胀、疼痛应","options":["减慢滴速","立即停止输液，拔针并处理","继续输入","热敷后继续"],"answer":1,"explanation":"输液局部肿胀疼痛提示药液外渗，应立即停止输液拔针，按药液性质处理。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2640","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行肌肉注射时，进针后应","options":["回抽无血后再推药","直接推药","边推边抽","先推药后回抽"],"answer":0,"explanation":"肌注进针后应回抽确认无血，防止药液误入血管。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2641","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行皮内注射时，正确的做法是","options":["注射后勿按压","用力按压","按摩局部","冰敷"],"answer":0,"explanation":"皮内注射后勿按压、勿揉擦，以免影响皮试结果。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2642","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行皮下注射胰岛素时，注射部位应","options":["定期轮换","固定一处","随意选择","避开腹部"],"answer":0,"explanation":"胰岛素注射应定期轮换部位，防止脂肪萎缩和吸收异常。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2643","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行雾化吸入后，应","options":["漱口并洗脸","立即进食","平卧","饮水后平卧"],"answer":0,"explanation":"雾化吸入含激素类药物后应漱口洗脸，防止口腔真菌感染和面部药物残留。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2644","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行导尿时，动作应","options":["轻柔，防止损伤尿道黏膜","快速插入","用力插入","反复插入"],"answer":0,"explanation":"导尿应轻柔操作，防止尿道黏膜损伤和感染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2645","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行灌肠时，如出现面色苍白、出冷汗应","options":["抬高灌肠筒","减慢速度","继续灌肠","立即停止灌肠并通知医生"],"answer":3,"explanation":"灌肠中出现面色苍白、出冷汗、剧烈腹痛应立即停止，通知医生处理。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2646","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行冷敷时，应观察的内容不包括","options":["皮肤有无冻伤","局部皮肤颜色","病人感觉","病人的饮食"],"answer":3,"explanation":"冷敷观察局部皮肤、感觉及有无冻伤，与饮食无关。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2647","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行热敷时，水温不宜超过","options":["80℃","70℃","50℃（特殊人群）","40℃"],"answer":2,"explanation":"热敷水温一般60～70℃，婴幼儿、老人、循环障碍者不超过50℃，防止烫伤。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2648","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行口腔护理时，发现口腔黏膜溃疡应","options":["用热水含漱","用酒精擦拭","涂西瓜霜或锡类散","不予处理"],"answer":2,"explanation":"口腔溃疡可涂西瓜霜、锡类散或溃疡膏，促进愈合。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2649","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行皮肤护理时，应重点检查","options":["骨隆突处皮肤","四肢","腹部","背部全部"],"answer":0,"explanation":"骨隆突处为压疮好发部位，应重点检查受压皮肤。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2650","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行晨间护理时，应协助","options":["外出","进食","运动","洗漱、翻身、整理床单位"],"answer":3,"explanation":"晨间护理包括协助洗漱、翻身、皮肤护理、整理床单位等。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2651","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行晚间护理时，应","options":["调暗灯光，保持病室安静","开灯照明","大声说话","增加探视"],"answer":0,"explanation":"晚间护理应调暗灯光、保持安静，协助病人入睡。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2652","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行鼻饲时，每次喂食前应","options":["直接注入","回抽胃液确认胃管在胃内","先注入温水","先注入药物"],"answer":1,"explanation":"鼻饲前回抽胃液确认胃管位置，防止误吸。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2653","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行氧气吸入时，应先","options":["调节氧流量后再插入鼻导管","先插管后调流量","随意顺序","关闭氧气"],"answer":0,"explanation":"先调流量后插管，防止大量氧气冲击呼吸道黏膜。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2654","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人停用氧气时，应先","options":["先关氧气","取下鼻导管再关氧气开关","随意顺序","拔管后关表"],"answer":1,"explanation":"停氧应先取下鼻导管再关氧气开关，防止关表不当致氧气外冲损伤呼吸道。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2655","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行心肺复苏时，按压深度为","options":["7～8cm","2～3cm","5～6cm","3～4cm"],"answer":2,"explanation":"成人CPR按压深度5～6cm，频率100～120次/分，保证胸廓充分回弹。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2656","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行海姆立克急救时，冲击部位为","options":["脐上两横指处","脐下","胸骨","背部"],"answer":0,"explanation":"海姆立克法冲击部位为腹部脐上两横指处，向内向上冲击。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2657","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行急救时，应遵循的原则是","options":["先救命后治病","先治病后救命","先转运后抢救","先检查后抢救"],"answer":0,"explanation":"急救原则为先救命后治病，优先处理危及生命的问题。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2658","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行转运时，应","options":["拔除所有管路","保持呼吸道通畅，妥善固定管路","随意搬运","不考虑体位"],"answer":1,"explanation":"转运危重病人应保持呼吸道通畅、妥善固定管路、防止脱出。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2659","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行出院指导时，应包括","options":["仅饮食","仅用药","用药、饮食、复诊及功能锻炼","仅复诊"],"answer":2,"explanation":"出院指导应全面，包括用药、饮食、活动、复诊等。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2660","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行入院介绍时，应介绍","options":["仅医生姓名","仅病房号","病区环境、规章制度、主管医护人员","仅护士站位置"],"answer":2,"explanation":"入院介绍包括病区环境、安全、制度、主管医生护士等，帮助病人适应。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2661","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行健康宣教时，应","options":["一律书面","一律口头","根据病人文化程度和理解能力选择方式","不考虑病人情况"],"answer":2,"explanation":"健康宣教应个体化，根据病人文化程度、接受能力选择合适方式。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2662","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行心理护理时，应","options":["倾听、共情，建立信任关系","说教","回避","批评"],"answer":0,"explanation":"心理护理以倾听、共情、支持为主，建立良好护患关系。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2663","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行疼痛评估时，常用的方法是","options":["数字评分法","观察法","询问家属","猜测"],"answer":0,"explanation":"疼痛评估常用数字评分法（NRS）、面部表情量表等，以病人主诉为准。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2664","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行营养评估时，应包括","options":["仅进食","仅体重","体重、进食情况、实验室指标","仅身高"],"answer":2,"explanation":"营养评估包括体重变化、进食情况、生化指标等综合判断。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2665","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行跌倒风险评估时，应包括","options":["仅身高","仅年龄","仅性别","年龄、用药史、既往跌倒史、平衡能力"],"answer":3,"explanation":"跌倒风险评估包括年龄、用药、既往史、平衡能力、环境等多因素。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2666","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行压疮风险评估时，常用的量表是","options":["Braden量表","GCS量表","VAS量表","APGAR量表"],"answer":0,"explanation":"压疮风险常用Braden量表；GCS为昏迷评分，VAS为疼痛评分。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2667","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行跌倒预防宣教时，应告知","options":["快速起床","起床时遵循“三部曲”，动作缓慢","穿拖鞋","不扶扶手"],"answer":1,"explanation":"预防跌倒应遵循起床三部曲（醒后躺30秒、坐30秒、站30秒），穿防滑鞋。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2668","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行管路护理时，应","options":["随意放置","妥善固定，防止脱出","不固定","自行拔除"],"answer":1,"explanation":"管路护理应妥善固定、标识清晰、防止脱出，观察引流情况。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2669","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行输血时，应","options":["单人核对","双人核对血型和病人信息","家属核对","医生核对"],"answer":1,"explanation":"输血必须双人核对血型、交叉配血结果及病人信息，确保安全。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2670","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行化疗时，应","options":["监测血常规，观察不良反应","仅观察体温","不监测","仅观察血压"],"answer":0,"explanation":"化疗期间监测血常规、肝肾功能，观察恶心、脱发等不良反应。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2671","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行术后护理时，应","options":["仅观察伤口","观察生命体征、伤口及引流情况","仅观察体温","仅观察血压"],"answer":1,"explanation":"术后护理应观察生命体征、伤口、引流、疼痛及并发症等。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2672","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行术前护理时，应","options":["仅禁食","隐瞒手术信息","仅备皮","讲解手术流程，进行适应性训练"],"answer":3,"explanation":"术前护理包括健康宣教、心理支持、适应性训练、备皮、禁食等。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2673","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行禁食护理时，应","options":["喂水","不予处理","让病人漱口","口腔护理每日2次"],"answer":3,"explanation":"禁食病人应做好口腔护理，防止口腔感染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2674","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行输液时，发现液体不滴应","options":["检查针头是否堵塞、脱出或体位不当","立即拔针","加快滴速","用力挤压"],"answer":0,"explanation":"液体不滴应查找原因：针头滑出、堵塞、体位不当或压力不足，对症处理。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2675","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行输血时，发现溶血反应应","options":["减慢速度","立即停止输血，保留静脉通路","继续输血","更换血袋继续"],"answer":1,"explanation":"溶血反应应立即停止输血，保留静脉通路，报告医生并抢救。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2676","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行氧气吸入时，湿化瓶应","options":["不更换","每周更换","每日更换湿化液","每月更换"],"answer":2,"explanation":"湿化瓶每日更换灭菌水，定期消毒，防止细菌滋生。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2677","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行吸痰时，负压成人一般为","options":["20kPa","40～53.3kPa","60kPa","70kPa"],"answer":1,"explanation":"成人吸痰负压40～53.3kPa，儿童33.3～40kPa。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2678","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行气管切开护理时，应","options":["减少护理","不吸痰","保持套管通畅，及时吸痰","仅换纱布"],"answer":2,"explanation":"气切护理应保持套管通畅、及时吸痰、清洁消毒内套管、更换敷料。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2679","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行鼻饲时，发现胃液呈咖啡色应","options":["继续鼻饲","暂停鼻饲并报告医生","加快速度","减少量"],"answer":1,"explanation":"咖啡色胃液提示消化道出血，应暂停鼻饲并报告医生。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2680","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医学的基本特点是","options":["整体观念和辨证论治","阴阳五行","望闻问切","精气学说"],"answer":0,"explanation":"中医学两大基本特点为整体观念与辨证论治。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2681","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"阴阳的基本含义是","options":["指天地","指太阳和月亮","对自然界相互关联的某些事物和现象对立双方的概括","指水火"],"answer":2,"explanation":"阴阳是宇宙中相互关联又相互对立的事物或现象属性的概括。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2682","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"“阴平阳秘，精神乃治”说明","options":["阴阳平衡是维持正常生命活动的基础","阴气要旺盛","阳气要旺盛","阴阳相互对立"],"answer":0,"explanation":"阴阳处于动态平衡，人体才能健康。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2683","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"五行中“土”的特性是","options":["生化、承载、受纳","生长、升发","收敛","寒凉滋润"],"answer":0,"explanation":"土性生化承载，主万物之化育。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2684","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"五行相生的顺序是","options":["木生火，火生土，土生金，金生水，水生木","木克土，土克水","水生木，木生土","火克金，金克木"],"answer":0,"explanation":"五行相生：木→火→土→金→水→木。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2685","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"五行相克的顺序是","options":["水克土","木克火","土克木","木克土，土克水，水克火，火克金，金克木"],"answer":3,"explanation":"五行相克：木克土、土克水、水克火、火克金、金克木。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2686","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心在五行属","options":["金","水","木","火"],"answer":3,"explanation":"心属火，肝属木，脾属土，肺属金，肾属水。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2687","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"“肺主一身之气”取决于","options":["肺的肃降","肺的宣发","肺的呼吸功能","肺朝百脉"],"answer":2,"explanation":"肺通过呼吸运动生成宗气，主一身之气。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2688","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脾主运化是指","options":["脾主肌肉","脾具有运化水谷精微和水液的功能","脾统血","脾主升清"],"answer":1,"explanation":"脾主运化包括运化水谷和运化水液两方面。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2689","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肾主水是指","options":["肾主纳气","肾藏精","肾具有主持和调节全身水液代谢的功能","肾主骨"],"answer":2,"explanation":"肾阳的气化作用主宰全身水液代谢。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2690","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肝主疏泄的功能不包括","options":["促进消化","调畅气机","调节情志","统摄血液"],"answer":3,"explanation":"肝主疏泄包括调畅气机、调节情志、促进消化，统血为脾的功能。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2691","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"称为“后天之本”的是","options":["心","肾","脾","肺"],"answer":2,"explanation":"脾主运化水谷，为气血生化之源，称后天之本；肾为先天之本。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2692","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"称为“水脏”的是","options":["肺","脾","肾","膀胱"],"answer":2,"explanation":"肾主水，为水脏；膀胱为水腑。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2693","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"“肺为水之上源”是因为","options":["肺主宣发肃降，通调水道","肺主气","肺朝百脉","肺主皮毛"],"answer":0,"explanation":"肺通过宣发肃降调节水液输布和排泄，故称水之上源。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2694","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"气血关系正确的是","options":["血能生气","气能生血、行血、摄血，血能载气","气能载血","二者无关"],"answer":1,"explanation":"气为血之帅，血为气之母，气血相互依存。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2695","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"“气为血之帅”是指","options":["血能载气","气能生血、行血、摄血","血能养气","气血同源"],"answer":1,"explanation":"气能推动和统摄血液运行，故称气为血之帅。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2696","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"津液的输布主要依靠","options":["脾肺肾肝等脏腑的协同作用","仅脾","仅肺","仅肾"],"answer":0,"explanation":"津液代谢依赖脾的转输、肺的宣降、肾的蒸腾气化等协同。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2697","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"经络系统中，十二经脉的命名依据不包括","options":["脏腑","阴阳","手足","五行"],"answer":1,"explanation":"十二经脉以手足、阴阳、脏腑命名，与五行无直接命名关系。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2698","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"十二经脉中，循行于上肢外侧前缘的是","options":["手太阴肺经","手阳明大肠经","手少阳三焦经","手太阳小肠经"],"answer":1,"explanation":"手阳明大肠经行于上肢外侧前缘。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2699","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"奇经八脉中，称为“血海”的是","options":["冲脉","任脉","督脉","带脉"],"answer":0,"explanation":"冲脉为血海；督脉为阳脉之海；任脉为阴脉之海。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2700","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"称为“阳脉之海”的是","options":["冲脉","督脉","带脉","阳跷脉"],"answer":1,"explanation":"督脉总督一身之阳经，为阳脉之海。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2701","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"六淫中，具有“善行数变”特点的是","options":["湿邪","寒邪","风邪","燥邪"],"answer":2,"explanation":"风邪善行数变，为百病之长，常兼夹他邪致病。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2702","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"湿邪的性质和致病特点不包括","options":["黏滞","重浊","易伤津液","易阻气机"],"answer":2,"explanation":"湿邪重浊黏滞、易阻遏气机、易伤脾阳；燥邪才易伤津液。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2703","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"七情致病最易损伤的脏腑是","options":["胆、胃","肺、肾","大肠、小肠","心、肝、脾"],"answer":3,"explanation":"七情过激主要伤及心、肝、脾三脏。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2704","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"“望神”中，病人表现为精神不振、面色少华属于","options":["假神","得神","失神","少神"],"answer":3,"explanation":"少神（神气不足）见于轻度失养或体虚；失神为精气亏损危重。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2705","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病人面色苍白或晦暗、精神萎靡、目光呆滞属于","options":["得神","失神","少神","神志清楚"],"answer":1,"explanation":"失神为精气衰败，病情危重之象。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2706","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"久病重病者突然精神转佳、颧红如妆属于","options":["少神","得神","假神","正常"],"answer":2,"explanation":"假神为阴阳离决前的回光返照，提示病情恶化。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2707","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"正常人面色为","options":["红黄隐隐，明润含蓄","苍白","萎黄","晦暗"],"answer":0,"explanation":"正常面色红黄隐隐、明润含蓄，为有胃气、有神气之象。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2708","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"面色发黄多主","options":["热证","寒证","痛证","脾虚、湿证"],"answer":3,"explanation":"黄色主脾虚、湿证；白色主寒证、失血；青色主寒、痛、瘀血。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2709","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"舌诊中，舌质的正常表现是","options":["淡白","深红","紫暗","淡红润泽"],"answer":3,"explanation":"正常舌质淡红润泽，苔薄白。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2710","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"舌苔白腻多提示","options":["热盛","痰湿内停","瘀血","阴虚"],"answer":1,"explanation":"白腻苔主痰湿、寒湿内停。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2711","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"舌红少苔或无苔多提示","options":["血瘀","寒湿","气虚","阴虚内热"],"answer":3,"explanation":"舌红少苔为阴虚火旺之象。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2712","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"问诊中，问寒热的类型不包括","options":["寒热错杂","恶寒发热","但热不寒","寒热往来"],"answer":3,"explanation":"问寒热包括恶寒发热、但寒不热、但热不寒、寒热往来，无“寒热错杂”类型。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2713","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"潮热的特点是","options":["按时发热或定时热甚，如潮汐","持续高热","低热不断","寒战"],"answer":0,"explanation":"潮热按时发热或定时热甚，有阴虚潮热、阳明潮热等类型。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2714","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"切脉的部位一般选择","options":["耳前动脉","足背动脉","颈动脉","寸口脉（桡动脉）"],"answer":3,"explanation":"切脉以寸口脉（腕部桡动脉）为主，分寸关尺三部。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2715","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"正常脉象的特点是","options":["一息六至以上","三部有脉，一息四至，不浮不沉","脉细如线","脉来结代"],"answer":1,"explanation":"平脉一息四至五至，从容和缓，节律一致。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2716","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脉象“浮脉”主","options":["表证","里证","寒证","虚证"],"answer":0,"explanation":"浮脉主表证，外邪袭表，脉浮而有力。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2717","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脉象“沉脉”主","options":["热证","表证","里证","风证"],"answer":2,"explanation":"沉脉主里证，病邪在里，脉沉。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2718","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"八纲辨证是指","options":["六经、卫气营血","气血、津液","脏腑、经络","阴阳、表里、寒热、虚实"],"answer":3,"explanation":"八纲为阴阳、表里、寒热、虚实，是辨证的总纲。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2719","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"实证的临床表现不包括","options":["神疲乏力","疼痛拒按","脉实有力","舌苔厚腻"],"answer":0,"explanation":"神疲乏力为虚证表现；实证多见疼痛拒按、脉实有力等。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2720","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"阴虚证的临床表现是","options":["面色苍白","畏寒肢冷","五心烦热、潮热盗汗、舌红少苔","脉沉迟"],"answer":2,"explanation":"阴虚证见五心烦热、潮热盗汗、口干咽燥、舌红少苔、脉细数。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2721","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"阳虚证的临床表现是","options":["潮热盗汗","五心烦热","畏寒肢冷、面色苍白、脉沉迟无力","舌红少苔"],"answer":2,"explanation":"阳虚证见畏寒肢冷、面色苍白、神疲乏力、脉沉迟无力。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2722","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"气虚证的临床表现是","options":["脉细数","五心烦热","潮热盗汗","神疲乏力、气短懒言、自汗"],"answer":3,"explanation":"气虚证见神疲乏力、气短懒言、自汗、舌淡脉虚无力。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2723","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"血虚证的临床表现是","options":["面色苍白或萎黄、头晕眼花、心悸","五心烦热","潮热盗汗","脉滑数"],"answer":0,"explanation":"血虚证见面色苍白或萎黄、唇甲色淡、头晕心悸、脉细。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2724","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脏腑辨证中，心气虚的典型表现是","options":["心悸、气短、活动后加重","咳嗽","腹泻","腰膝酸软"],"answer":0,"explanation":"心气虚见心悸气短、活动后加重、神疲乏力。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2725","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肺气虚的典型表现是","options":["五心烦热","心悸","腹泻","咳喘无力、气短、自汗畏风"],"answer":3,"explanation":"肺气虚见咳喘无力、气短声低、自汗畏风、易感冒。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2726","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脾胃虚寒的典型表现是","options":["五心烦热","腹痛拒按","便秘","腹痛喜温喜按、大便稀溏"],"answer":3,"explanation":"脾胃虚寒见腹痛绵绵、喜温喜按、食少便溏、畏寒肢冷。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2727","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肾阳虚的典型表现是","options":["腰膝酸冷、畏寒肢冷、夜尿多","五心烦热","潮热盗汗","舌红少苔"],"answer":0,"explanation":"肾阳虚见腰膝酸冷、畏寒肢冷、夜尿频多、舌淡苔白。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2728","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中药四气是指","options":["升、降、浮、沉","酸、苦、甘、辛","寒、热、温、凉","归经"],"answer":2,"explanation":"中药四气（四性）为寒热温凉；五味为酸苦甘辛咸。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2729","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中药五味中，具有“补益、和中、缓急”作用的是","options":["辛味","酸味","苦味","甘味"],"answer":3,"explanation":"甘味能补益、和中、缓急；辛味能散能行；酸味能收能涩。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2730","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中药五味中，具有“发散、行气、行血”作用的是","options":["酸味","甘味","辛味","咸味"],"answer":2,"explanation":"辛味能散、能行，用于发散表邪、行气活血。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2731","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中药“归经”是指","options":["药物的毒性","药物的产地","药物的采收时间","药物对某脏腑经络的选择性作用"],"answer":3,"explanation":"归经指药物作用对机体某部分（脏腑经络）的选择性。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2732","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中药煎煮时，需要先煎的药物是","options":["砂仁","薄荷","矿物类、贝壳类药材","钩藤"],"answer":2,"explanation":"矿物、贝壳类质地坚硬，有效成分不易煎出，需先煎30分钟以上。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2733","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中药煎煮时，需要后下的药物是","options":["龙骨","石膏","气味芳香的解表药","牡蛎"],"answer":2,"explanation":"薄荷、砂仁等芳香易挥发药物宜后下，煎煮5分钟左右。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2734","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中药煎煮时，需要包煎的药物是","options":["附子","人参","车前子、旋覆花","大黄"],"answer":2,"explanation":"细小种子类和有绒毛的药物需包煎，防止浑浊或刺激咽喉。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2735","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中药煎煮时，需要烊化的药物是","options":["阿胶","黄连","黄芩","黄柏"],"answer":0,"explanation":"胶类药材如阿胶需烊化（隔水炖化）后兑入药汁。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2736","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"汤剂服药时间，一般","options":["睡前","立即饭后","饭前或饭后1小时左右","空腹"],"answer":2,"explanation":"汤剂一般饭前或饭后1小时服用，对胃肠刺激大的药物宜饭后服。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2737","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"驱虫药宜在","options":["空腹时服用","饭后服用","睡前服用","随时服用"],"answer":0,"explanation":"驱虫药宜空腹服，使药物迅速入肠，利于驱虫。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2738","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"安神药宜在","options":["睡前服用","晨起服用","饭前服用","饭后服用"],"answer":0,"explanation":"安神药宜睡前半小时至1小时服用，利于入睡。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2739","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"方剂中“君药”是指","options":["用量最大的药","针对主病或主证起主要治疗作用的药物","辅助君药的药","调和诸药的药"],"answer":1,"explanation":"君药针对主病主证起主要作用，为方剂核心。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2740","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"方剂组成中“使药”的作用是","options":["引经或调和诸药","主要治疗","辅助治疗","直接攻邪"],"answer":0,"explanation":"使药起引经报使或调和诸药的作用。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2741","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"银翘散的功用是","options":["泻下通便","辛温解表","辛凉透表，清热解毒","温补阳气"],"answer":2,"explanation":"银翘散为辛凉解表代表方，主治风热感冒。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2742","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"麻黄汤的组成不包括","options":["石膏","杏仁","桂枝","麻黄"],"answer":2,"explanation":"麻黄汤由麻黄、桂枝、杏仁、甘草组成，无石膏。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2743","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"四君子汤的功用是","options":["益气健脾","补血养血","滋阴降火","温阳散寒"],"answer":0,"explanation":"四君子汤（人参、白术、茯苓、甘草）为益气健脾基础方。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2744","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"四物汤的组成是","options":["人参、白术、茯苓、甘草","当归、川芎、白芍、熟地黄","黄芪、当归","熟地黄、山萸肉"],"answer":1,"explanation":"四物汤为补血调血基础方，由当归、川芎、白芍、熟地组成。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2745","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"补中益气汤的功用是","options":["温阳利水","清热解毒","滋阴补肾","补中益气，升阳举陷"],"answer":3,"explanation":"补中益气汤补中益气、升阳举陷，主治脾胃气虚及气虚下陷证。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2746","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"六味地黄丸的功用是","options":["温补肾阳","滋阴补肾","益气健脾","清热泻火"],"answer":1,"explanation":"六味地黄丸为滋阴补肾代表方，主治肾阴虚证。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2747","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肾气丸的功用是","options":["滋阴降火","温补肾阳","益气固表","清热利湿"],"answer":1,"explanation":"肾气丸（金匮肾气丸）温补肾阳，主治肾阳不足证。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2748","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"针灸学中，手三阴经的循行方向是","options":["从头走足","从手走胸","从手走头","从胸走手"],"answer":3,"explanation":"手三阴经从胸走手，手三阳经从手走头，足三阳经从头走足，足三阴经从足走腹。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2749","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"足三阴经的循行方向是","options":["从足走头","从腹走足","从足走腹","从头走足"],"answer":2,"explanation":"足三阴经从足走腹（胸），交手三阴经。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2750","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"常用的腧穴定位方法不包括","options":["骨度分寸法","五行定位法","体表标志法","手指同身寸法"],"answer":1,"explanation":"腧穴定位常用骨度分寸、体表标志、手指同身寸和简便取穴法，无五行定位法。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2751","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"合谷穴位于","options":["腕横纹上","手背第1、2掌骨之间","肘横纹处","肩部"],"answer":1,"explanation":"合谷穴位于手背第1、2掌骨间，第2掌骨桡侧中点处。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2752","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"足三里穴位于","options":["犊鼻下3寸","犊鼻下5寸","内踝上3寸","脐下3寸"],"answer":0,"explanation":"足三里位于犊鼻（外膝眼）下3寸，胫骨前嵴外一横指处。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2753","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"三阴交穴位于","options":["足背","外踝尖上3寸","内踝尖上5寸","内踝尖上3寸"],"answer":3,"explanation":"三阴交位于内踝尖上3寸，胫骨内侧缘后方，为肝脾肾三经交会穴。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2754","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"百会穴位于","options":["头顶正中线与两耳尖连线交点","前发际正中直上1寸","后发际正中直上1寸","耳后"],"answer":0,"explanation":"百会穴位于头顶正中线与两耳尖连线的交点处。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2755","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"涌泉穴位于","options":["足底前1/3凹陷处","足背","足跟","足趾"],"answer":0,"explanation":"涌泉穴位于足底第2、3趾缝纹头端与足跟连线的前1/3处。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2756","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"针刺时，病人出现晕针应","options":["继续针刺","立即出针，让病人平卧，饮温水","加大刺激","不留针"],"answer":1,"explanation":"晕针应立即出针，平卧、保暖、饮温水，重者掐人中并抢救。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2757","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"拔罐的主要作用不包括","options":["温补阳气","行气活血","祛风散寒","消肿止痛"],"answer":0,"explanation":"拔罐有行气活血、祛风散寒、消肿止痛等作用，不以温补阳气为主。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2758","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"刮痧的作用不包括","options":["清热解毒","发汗解表","舒筋活络","温阳散寒"],"answer":3,"explanation":"刮痧有发汗解表、舒筋活络、清热解毒等作用，不以温阳散寒为主。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2759","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"推拿的适应证不包括","options":["腰肌劳损","颈椎病","骨折早期","小儿腹泻"],"answer":2,"explanation":"骨折早期为推拿禁忌，以免加重损伤。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2760","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“治未病”思想是指","options":["只防不治","只治已病","不治病","未病先防，既病防变"],"answer":3,"explanation":"治未病包括未病先防和既病防变两方面。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2761","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医养生的基本原则不包括","options":["起居有常","顺应自然","过度劳累","饮食有节"],"answer":2,"explanation":"养生强调顺应自然、起居有常、饮食有节、劳逸适度，过度劳累违背养生原则。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2762","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“精”的概念是指","options":["仅指水谷之精","仅指生殖之精","构成人体和维持生命活动的基本物质","仅指血液"],"answer":2,"explanation":"精是构成人体、维持生命活动的基本物质，包括先天之精和后天之精。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2763","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“神”的产生基础是","options":["津液","血液","精气","营气"],"answer":2,"explanation":"神以精为基础，精化气，气化神。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2764","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“津液”的功能不包括","options":["产生津液","化生血液","运输营养物质","濡养脏腑"],"answer":3,"explanation":"津液有濡养、化血、运输等功能，本身不产生津液。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2765","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“气”的功能不包括","options":["温煦","固摄","气化","凝固"],"answer":0,"explanation":"气的功能包括推动、温煦、防御、固摄、气化，无“凝固”功能。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2766","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“气化”是指","options":["气的固摄","气的升降","气的出入","气的运动产生的各种变化"],"answer":3,"explanation":"气化指气的运动（升降出入）产生的各种变化，如物质转化。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2767","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“宗气”的生成来源是","options":["自然界的清气和脾胃化生的水谷精气","先天之精","肾气","卫气"],"answer":0,"explanation":"宗气由肺吸入的清气与脾胃化生的水谷精气结合而成。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2768","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“卫气”的主要功能是","options":["化生血液","推动血液运行","护卫肌表，温养脏腑，调节汗孔开合","固摄精液"],"answer":2,"explanation":"卫气行于脉外，护卫肌表、温养脏腑、调节汗孔开合。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2769","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“营气”的主要功能是","options":["化生血液，营养全身","护卫肌表","调节汗孔","推动气血"],"answer":0,"explanation":"营气行于脉中，化生血液、营养全身。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2770","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“血府”是指","options":["肝","心","脉","脾"],"answer":2,"explanation":"脉为血之府，血液运行之通道。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2771","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“娇脏”是指","options":["肝","肺","脾","肾"],"answer":1,"explanation":"肺为娇脏，清虚娇嫩，易受外邪侵袭。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2772","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“刚脏”是指","options":["肺","肝","心","脾"],"answer":1,"explanation":"肝为刚脏，主升主动，体阴用阳。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2773","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“胃”的生理功能是","options":["输布精微","运化水谷","受纳腐熟水谷","排泄尿液"],"answer":2,"explanation":"胃主受纳腐熟水谷，为水谷之海。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2774","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“小肠”的主要生理功能是","options":["传导糟粕","受纳腐熟","运化水液","受盛化物，泌别清浊"],"answer":3,"explanation":"小肠受盛化物、泌别清浊，分清别浊。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2775","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“大肠”的主要生理功能是","options":["受盛化物","传导糟粕","泌别清浊","运化水谷"],"answer":1,"explanation":"大肠主传导糟粕，将食物残渣形成粪便排出。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2776","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“膀胱”的主要生理功能是","options":["输布津液","受纳水谷","化生尿液","贮尿和排尿"],"answer":3,"explanation":"膀胱主贮尿和排尿，依赖肾阳气化。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2777","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“三焦”的概念是","options":["一个穴位","一个脏腑","上焦、中焦、下焦的合称","一种病名"],"answer":2,"explanation":"三焦为六腑之一，为上中下三焦的合称，主通行元气和水液。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2778","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“心主血脉”是指","options":["心气推动血液在脉中运行","心化生血液","心藏神","心开窍于舌"],"answer":0,"explanation":"心主血脉包括主血和主脉两方面，心气推动血液运行。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2779","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“肝藏血”是指","options":["肝行血","肝化生血液","肝统血","肝具有贮藏血液和调节血量的功能"],"answer":3,"explanation":"肝藏血包括贮藏血液、调节血量、防止出血等。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2780","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"流行病学研究的对象是","options":["单个病人","人群","动物","细胞"],"answer":1,"explanation":"流行病学以人群为研究对象，研究疾病、健康状态的分布及影响因素。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2781","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"流行病学研究中最基本的方法是","options":["数学模型法","实验法","观察法","访谈法"],"answer":2,"explanation":"流行病学以观察法为最基本方法，包括描述性和分析性研究。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2782","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"描述疾病流行强度的术语不包括","options":["流行","暴发","散发","转归"],"answer":2,"explanation":"疾病流行强度分为散发、暴发、流行和大流行，转归为疾病结局。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2783","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"某病发病率呈历年一般水平称为","options":["大流行","暴发","散发","聚集性"],"answer":2,"explanation":"散发指发病率呈历年一般水平，病例间无明显联系。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2784","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"表示疾病发生强度的指标是","options":["发病率","患病率","死亡率","病死率"],"answer":0,"explanation":"发病率反映疾病新发病例发生的强度。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2785","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患病率是指","options":["某病死亡数","某期间新发病例数","某特定时间内某病新旧病例数占同期平均人口数的比例","某病治愈数"],"answer":2,"explanation":"患病率=某时期新旧病例总数/同期平均人口数，反映患病总量。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2786","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发病率与患病率的关系是","options":["患病率取决于发病率和病程","患病率仅取决于发病率","二者无关","发病率取决于患病率"],"answer":0,"explanation":"患病率≈发病率×病程，病程长则患病率高。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2787","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"某病病死率是指","options":["该病患者中死于该病的比例","该病死亡数占人口比例","该病治愈比例","该病复发比例"],"answer":0,"explanation":"病死率=死于某病的例数/该病患病总例数，反映疾病严重程度。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2788","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"死亡率是指","options":["某病死亡比例","某期间死于所有原因的人数占同期平均人口数的比例","婴儿死亡比例","意外死亡比例"],"answer":1,"explanation":"死亡率=同期死亡总人数/同期平均人口数，为全死因死亡强度指标。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2789","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"反映疾病治疗效果的近期指标是","options":["发病率","治愈率","患病率","死亡率"],"answer":1,"explanation":"治愈率、有效率等反映疾病近期治疗效果。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2790","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"队列研究的性质是","options":["前瞻性（由因到果）","回顾性（由果到因）","横断面","个案调查"],"answer":0,"explanation":"队列研究按暴露与否分组，前瞻性追踪结局，由因到果。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2791","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病例对照研究的性质是","options":["实验性","前瞻性","回顾性（由果到因）","干预性"],"answer":2,"explanation":"病例对照研究以病例和对照为对象，回顾暴露史，由果到因。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2792","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病例对照研究中最主要的偏倚是","options":["失访偏倚","回忆偏倚","测量偏倚","混杂偏倚"],"answer":1,"explanation":"病例对照研究需回忆暴露史，易发生回忆偏倚。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2793","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"衡量某因素与疾病关联强度的指标是","options":["相对危险度（RR）","发病率","死亡率","患病率"],"answer":0,"explanation":"RR为暴露组与非暴露组发病率之比，反映关联强度。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2794","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"RR值大于1说明","options":["无法判断","呈负相关","无关联","暴露因素与疾病呈正相关（危险因素）"],"answer":3,"explanation":"RR>1表示暴露增加疾病风险，为危险因素；RR<1为保护因素。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2795","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"队列研究中常见的偏倚是","options":["测量偏倚","回忆偏倚","选择偏倚","失访偏倚"],"answer":3,"explanation":"队列研究随访时间长，失访偏倚最常见。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2796","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"实验流行病学与观察性研究的根本区别是","options":["样本大小","是否人为施加干预","研究时间","研究对象"],"answer":1,"explanation":"实验研究由研究者人为施加干预措施，观察性研究不施加干预。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2797","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临床试验中，随机分组的目的是","options":["增加样本量","平衡两组的混杂因素","减少费用","方便操作"],"answer":1,"explanation":"随机化使已知和未知的混杂因素在组间均衡分布。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2798","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临床试验中双盲是指","options":["研究者和受试者均不知分组情况","仅受试者不知","仅研究者不知","统计分析者不知"],"answer":0,"explanation":"双盲指研究者和受试者均不知分组情况，减少偏倚。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2799","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"筛检试验的目的是","options":["从外表健康者中查出可能患某病的人","确诊疾病","治疗疾病","预防疾病"],"answer":0,"explanation":"筛检是运用快速简便的试验从外表健康人群中找出可疑患病者。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2800","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"筛检试验中，灵敏度是指","options":["实际无病者中被筛检为阴性的比例","实际有病者中被筛检为阳性的比例","筛检阳性者中患病的比例","筛检阴性者中无病的比例"],"answer":1,"explanation":"灵敏度=真阳性/(真阳性+假阴性)，反映发现病人的能力。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2801","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"筛检试验中，特异度是指","options":["筛检阳性者中患病的比例","实际有病者中被筛检为阳性的比例","实际无病者中被筛检为阴性的比例","筛检阴性者中患病的比例"],"answer":2,"explanation":"特异度=真阴性/(真阴性+假阳性)，反映排除非病人的能力。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2802","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"提高筛检试验灵敏度的结果是","options":["准确性提高","假阴性增加","假阳性减少","假阴性减少，假阳性增加"],"answer":3,"explanation":"灵敏度提高时更多病人被检出，假阴性减少，但假阳性可能增加。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2803","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"评价筛检试验真实性的指标是","options":["灵敏度和特异度","阳性预测值","阴性预测值","可靠性"],"answer":0,"explanation":"灵敏度和特异度反映试验的真实性；可靠性反映重复性。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2804","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"传染病的流行过程必须具备的三个环节是","options":["传染源、传播途径、易感人群","病原体、宿主、环境","症状、体征、化验","潜伏期、前驱期、恢复期"],"answer":0,"explanation":"传染病流行需传染源、传播途径、易感人群三环节同时存在。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2805","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"传染源是指","options":["体内有病原体生长繁殖并能排出病原体的人和动物","病原体携带者","易感者","康复者"],"answer":0,"explanation":"传染源包括病人、病原携带者和受感染的动物。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2806","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"经空气传播的传染病，其流行特征是","options":["呈食物型暴发","夏季高发","冬春季高发，儿童多见","接触传播为主"],"answer":2,"explanation":"空气传播传染病多见于冬春季，儿童发病率高，传播广泛。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2807","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"经水传播的传染病，其流行特征是","options":["病例分布与供水范围一致，可呈暴发","冬春季高发","仅散发","与接触有关"],"answer":0,"explanation":"经水传播常呈暴发或流行，病例集中于供水范围。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2808","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"潜伏期是指","options":["病原体侵入机体至出现临床症状的这段时间","发病至痊愈的时间","传染期","恢复期"],"answer":0,"explanation":"潜伏期为病原体侵入至首发症状的时间，用于确定检疫期。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2809","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"确定传染病检疫期的重要依据是","options":["潜伏期","前驱期","恢复期","传染期"],"answer":0,"explanation":"检疫期按该病最长潜伏期确定。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2810","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"预防传染病最有效的措施是","options":["仅消毒","仅隔离","针对流行三环节的综合措施","仅治疗"],"answer":2,"explanation":"传染病防控采取管理传染源、切断传播途径、保护易感人群的综合措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2811","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"人工主动免疫是","options":["接种疫苗使机体产生特异性免疫","注射免疫球蛋白","注射抗生素","输血"],"answer":0,"explanation":"人工主动免疫通过接种疫苗刺激机体产生抗体和细胞免疫。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2812","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"人工被动免疫是","options":["接种疫苗","注射免疫球蛋白或抗毒素使机体立即获得免疫力","口服疫苗","自然感染"],"answer":1,"explanation":"人工被动免疫注射现成抗体，起效快但维持时间短。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2813","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国计划免疫（免疫规划）的疫苗不包括","options":["乙肝疫苗","卡介苗","流感疫苗","脊灰疫苗"],"answer":2,"explanation":"国家免疫规划疫苗包括卡介苗、乙肝、脊灰、百白破、麻疹等，流感为自费非规划疫苗。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2814","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"新生儿出生后24小时内应接种的疫苗是","options":["乙肝疫苗和卡介苗","麻疹疫苗","百白破疫苗","脊灰疫苗"],"answer":0,"explanation":"新生儿24小时内接种乙肝疫苗第1剂和卡介苗。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2815","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国法定传染病分为","options":["甲、乙两类","甲、乙、丙三类","甲、乙、丙、丁四类","仅甲类"],"answer":1,"explanation":"法定传染病分甲类（2种）、乙类、丙类。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2816","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"属于甲类传染病的是","options":["艾滋病","霍乱","麻疹","伤寒"],"answer":1,"explanation":"甲类传染病为鼠疫和霍乱，实行强制管理。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2817","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发现甲类传染病病人，报告时限为","options":["2小时内","12小时内","24小时内","48小时内"],"answer":0,"explanation":"甲类传染病及乙类中按甲类管理的病种应于2小时内网络直报。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2818","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发现乙类传染病病人，报告时限为","options":["72小时内","2小时内","48小时内","24小时内"],"answer":3,"explanation":"乙类、丙类传染病应于24小时内网络直报。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2819","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"对甲类传染病病人应采取的措施是","options":["仅随访","居家观察","无需隔离","强制隔离治疗"],"answer":3,"explanation":"甲类传染病病人和病原携带者应予以隔离治疗，隔离期按医学检查结果确定。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2820","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"切断传播途径的主要措施是","options":["预防服药","接种疫苗","隔离病人","消毒、杀虫、改善环境卫生"],"answer":3,"explanation":"切断传播途径以消毒、杀虫和一般卫生措施为主。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2821","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"保护易感人群的主要措施是","options":["预防接种","隔离病人","消毒","杀虫"],"answer":0,"explanation":"预防接种（计划免疫）是保护易感人群的最有效措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2822","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"环境污染物对健康的危害不包括","options":["急性危害","慢性危害","远期危害","免疫增强"],"answer":0,"explanation":"环境污染可致急性、慢性及远期危害（致癌、致畸、致突变），不会增强免疫。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2823","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"室内空气污染的主要来源不包括","options":["室外大气污染","建筑材料","燃料燃烧","吸烟"],"answer":0,"explanation":"室内空气污染主要来自建筑材料（氡）、燃料燃烧、吸烟、装修等，室外大气污染非主要来源。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2824","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"饮用水消毒的主要目的是","options":["软化水质","去除异味","去除重金属","杀灭水中的病原微生物"],"answer":3,"explanation":"饮用水消毒以杀灭病原微生物、防止介水传染病为目的。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2825","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国生活饮用水卫生标准规定，管网末梢水中游离性余氯不应低于","options":["0.05mg/L","0.5mg/L","0.3mg/L","1mg/L"],"answer":0,"explanation":"出厂水游离氯≥0.3mg/L，管网末梢水≥0.05mg/L。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2826","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"食物中毒的特点不包括","options":["潜伏期短","传染性","同食者集体发病","症状相似"],"answer":1,"explanation":"食物中毒无传染性，呈暴发、症状相似、停止食用后不再发病。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2827","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"细菌性食物中毒的主要表现是","options":["急性胃肠炎症状","神经系统症状","皮疹","关节痛"],"answer":0,"explanation":"细菌性食物中毒以急性胃肠炎症状为主，如恶心、呕吐、腹痛、腹泻。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2828","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"沙门菌食物中毒的常见食品是","options":["肉类及其制品","水果","蔬菜","谷物"],"answer":0,"explanation":"沙门菌食物中毒多由肉、蛋、奶及其制品引起。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2829","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"副溶血性弧菌食物中毒的常见食品是","options":["豆制品","谷物","海产品","乳制品"],"answer":2,"explanation":"副溶血性弧菌嗜盐，常见于海产品及盐腌食品。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2830","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"河豚鱼中毒的主要表现是","options":["胃肠炎症状","神经系统症状（口唇麻木、四肢无力）","皮疹","发热"],"answer":1,"explanation":"河豚毒素主要损害神经系统，表现为口唇麻木、四肢无力、呼吸困难。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2831","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"亚硝酸盐中毒的特效解毒剂是","options":["阿托品","亚甲蓝","解磷定","纳洛酮"],"answer":1,"explanation":"亚硝酸盐中毒致高铁血红蛋白血症，用亚甲蓝（美蓝）解救。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2832","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"有机磷农药中毒的特效解毒剂是","options":["地塞米松","亚甲蓝","纳洛酮","阿托品和解磷定"],"answer":3,"explanation":"有机磷中毒用阿托品对抗毒蕈碱症状，胆碱酯酶复能剂（解磷定）恢复酶活性。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2833","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"一氧化碳中毒的机制是","options":["形成碳氧血红蛋白，导致缺氧","抑制呼吸中枢","损伤肝脏","溶血"],"answer":0,"explanation":"CO与血红蛋白结合形成碳氧血红蛋白，使血红蛋白失去携氧能力。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2834","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"职业病的诊断依据不包括","options":["现场劳动卫生调查","职业史","病人的主观意愿","临床表现与实验室检查"],"answer":2,"explanation":"职业病诊断依据职业史、现场调查、临床表现及实验室检查，不依据主观意愿。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2835","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国法定职业病报告制度要求","options":["不报告","确诊后按规定报告","仅口头报告","延迟报告"],"answer":1,"explanation":"职业病确诊后应按规定时限报告，实行网络直报。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2836","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"尘肺病的主要预防措施是","options":["仅通风","仅戴口罩","湿式作业、密闭尘源、个体防护","仅体检"],"answer":2,"explanation":"尘肺预防采取湿式作业、密闭尘源、通风除尘、个体防护等综合措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2837","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"噪声对人体的主要危害是","options":["贫血","消化性溃疡","皮肤病","听力损伤"],"answer":3,"explanation":"长期噪声暴露致听力下降，严重者噪声性耳聋。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2838","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"生产性毒物进入人体的主要途径是","options":["呼吸道","消化道","皮肤","眼睛"],"answer":0,"explanation":"生产性毒物以呼吸道吸入为主要进入途径。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2839","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"铅中毒的典型表现是","options":["皮疹","腹绞痛、贫血、周围神经炎","发热","关节痛"],"answer":1,"explanation":"慢性铅中毒表现为腹绞痛、贫血、周围神经炎、铅线等。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2840","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"苯中毒的主要危害是","options":["心脏损害","肝脏损害","肾脏损害","造血系统损害（白细胞减少）"],"answer":3,"explanation":"慢性苯中毒主要损害造血系统，致白细胞减少、再生障碍性贫血。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2841","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"矽肺的致病因素是","options":["棉尘","煤尘","游离二氧化硅粉尘","木尘"],"answer":2,"explanation":"矽肺由长期吸入含游离二氧化硅的粉尘引起。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2842","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"健康的概念是","options":["没有疾病","身体、心理和社会适应的完好状态，而不仅是没有疾病","体格强壮","心理正常"],"answer":1,"explanation":"WHO定义健康为身体、心理和社会适应的完好状态。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2843","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"影响健康的主要因素不包括","options":["行为生活方式","环境因素","医疗技术","生物遗传因素"],"answer":2,"explanation":"影响健康的四大因素为环境、行为生活方式、生物遗传和医疗卫生服务，医疗技术非主要因素。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2844","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"健康促进的三大策略是","options":["倡导、赋权、协调","宣传、教育、治疗","预防、治疗、康复","管理、监督、评价"],"answer":0,"explanation":"健康促进三大策略为倡导（advocacy）、赋权（enable）、协调（mediation）。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2845","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"健康教育的核心是","options":["体检","宣传疾病知识","发放宣传资料","促使人们改变不良行为和生活方式"],"answer":3,"explanation":"健康教育以行为干预为核心，促使人们建立健康行为。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2846","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"初级卫生保健的基本内容不包括","options":["疾病预防","健康教育","专科治疗","基本治疗"],"answer":2,"explanation":"初级卫生保健包括健康教育、预防接种、基本医疗等，不包括专科治疗。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2847","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国卫生工作的方针是","options":["以专科为重点","以治疗为中心","以城市为中心","以基层为重点，以改革创新为动力，预防为主，中西医并重"],"answer":3,"explanation":"新时代卫生与健康工作方针：以基层为重点，以改革创新为动力，预防为主，中西医并重，将健康融入所有政策，人民共建共享。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2848","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"三级预防中的第二级预防是指","options":["临床预防","病因预防","康复预防","“三早”预防（早发现、早诊断、早治疗）"],"answer":3,"explanation":"第一级预防为病因预防；第二级为“三早”；第三级为临床预防、康复。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2849","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"三级预防中的第一级预防是指","options":["病因预防（针对致病因素）","早发现","早治疗","康复"],"answer":0,"explanation":"第一级预防针对病因和健康促进，是最积极的预防措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2850","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"慢性病的主要危险因素不包括","options":["不合理膳食","吸烟","缺乏运动","接种疫苗"],"answer":1,"explanation":"慢性病危险因素包括吸烟、不合理膳食、缺乏运动、过量饮酒等，接种疫苗为保护因素。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2851","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"高血压的主要危险因素是","options":["适量运动","低盐饮食","高盐饮食、超重、精神紧张","戒烟"],"answer":2,"explanation":"高盐饮食、超重肥胖、精神紧张、过量饮酒为高血压主要危险因素。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2852","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"糖尿病的主要危险因素是","options":["运动","肥胖、缺乏运动、遗传","低糖饮食","正常体重"],"answer":1,"explanation":"2型糖尿病主要危险因素为肥胖、缺乏运动、遗传及不合理膳食。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2853","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"吸烟对健康的主要危害不包括","options":["心血管疾病","肺癌","增强免疫力","慢性阻塞性肺疾病"],"answer":2,"explanation":"吸烟是肺癌、心血管疾病、COPD等的重要危险因素，不增强免疫力。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2854","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"过量饮酒对健康的主要危害不包括","options":["肝脏损害","增强记忆力","神经系统损害","消化系统损害"],"answer":1,"explanation":"过量饮酒致肝损害、神经系统损害、消化系统疾病等，不增强记忆力。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2855","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"合理膳食的基本要求不包括","options":["高盐高脂","食物多样","荤素搭配","适量摄入"],"answer":0,"explanation":"合理膳食要求食物多样、荤素搭配、适量摄入、低盐低脂。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2856","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中国居民膳食指南建议成人每日食盐摄入量不超过","options":["15克","10克","5克","20克"],"answer":2,"explanation":"膳食指南建议成人每日食盐不超过5克，食用油25～30克。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2857","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中国居民膳食指南建议成人每日添加糖摄入量不超过","options":["100克","50克（最好25克以下）","150克","200克"],"answer":1,"explanation":"每日添加糖不超过50克，最好控制在25克以下。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2858","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"体质指数（BMI）的计算公式是","options":["体重×身高","体重/身高","身高/体重","体重（kg）/身高（m）的平方"],"answer":3,"explanation":"BMI=体重（kg）/[身高（m）]²，18.5～23.9为正常。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2859","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国成人超重的BMI标准是","options":["BMI≥30","BMI≥28","24≤BMI<28","BMI≥25"],"answer":2,"explanation":"我国成人：18.5～23.9正常，24～27.9超重，≥28肥胖。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2860","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"有氧运动的主要特点是","options":["高强度短时间","中等强度、有节奏、持续时间较长","无规律","仅力量训练"],"answer":1,"explanation":"有氧运动如快走、慢跑、游泳，中等强度、持续时间较长。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2861","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"建议成人每周进行中等强度运动的时间为","options":["300分钟","30分钟","150分钟以上","600分钟"],"answer":2,"explanation":"WHO建议成人每周至少150分钟中等强度有氧运动。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2862","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"突发公共卫生事件的特点不包括","options":["公共属性","突发性","可预测性","危害严重"],"answer":2,"explanation":"突发公共卫生事件具有突发性、公共属性、危害严重、复杂性等特点，不可预测。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2863","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"突发公共卫生事件应急处理的原则是","options":["隐瞒信息","各自为政","延迟处理","统一领导、分级负责、反应及时、措施果断"],"answer":3,"explanation":"应急处理坚持统一领导、分级负责、反应及时、措施果断、依靠科学、加强合作。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2864","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"突发公共卫生事件报告的时限为","options":["24小时内","2小时内","12小时内","48小时内"],"answer":1,"explanation":"较大以上突发事件应在2小时内报告。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2865","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"消毒的目的不包括","options":["杀灭或清除传播媒介上的病原微生物","增强人体免疫力","预防感染","控制疫情"],"answer":1,"explanation":"消毒针对病原微生物，不增强人体免疫力。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2866","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"疫源地消毒中，随时消毒是指","options":["终末消毒","传染源离开后的消毒","预防性消毒","有传染源存在时对其排出物及污染场所进行的消毒"],"answer":3,"explanation":"随时消毒在传染源存在时进行；终末消毒在传染源离开后进行。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2867","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"杀虫的主要目的是","options":["消灭细菌","消灭老鼠","消灭传播疾病的节肢动物","消灭病毒"],"answer":2,"explanation":"杀虫针对蚊、蝇、蚤等节肢动物，切断虫媒传播途径。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2868","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"灭鼠的主要目的是","options":["消灭昆虫","消灭鼠类传染源和破坏其传播途径","消灭细菌","消灭病毒"],"answer":1,"explanation":"鼠类为多种传染病传染源和媒介，灭鼠属针对传染源和传播途径的措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2869","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"地方性甲状腺肿的主要原因是","options":["缺碘","缺钙","缺铁","缺锌"],"answer":0,"explanation":"碘缺乏致地方性甲状腺肿，严重者致克汀病。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2870","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"地方性氟中毒的主要原因是","options":["长期摄入过量氟","缺氟","缺钙","缺硒"],"answer":0,"explanation":"氟中毒致氟斑牙和氟骨症，由饮水或燃煤氟污染引起。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2871","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"克山病的病因与哪种元素缺乏有关","options":["铁","硒","锌","铜"],"answer":1,"explanation":"克山病与缺硒有关，补硒可预防。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2872","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"儿童青少年近视的主要预防措施是","options":["多看书","增加户外活动时间，控制用眼时间","多看电视","不运动"],"answer":1,"explanation":"每天2小时以上户外活动、控制近距离用眼时间是预防近视的有效措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2873","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"学校卫生中，教室课桌面照度不应低于","options":["100lx","50lx","300lx","1000lx"],"answer":2,"explanation":"教室课桌面维持平均照度不低于300lx，黑板不低于500lx。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2874","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"老年人健康管理的重点是","options":["仅体检","慢病管理、功能维护、预防跌倒","仅用药","仅运动"],"answer":1,"explanation":"老年人健康管理以慢病管理、功能维护、跌倒预防、心理健康为重点。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2875","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"妇幼保健的主要内容不包括","options":["计划生育技术服务","孕产期保健","儿童保健","专科手术"],"answer":3,"explanation":"妇幼保健包括孕产期保健、儿童保健、生殖健康等，不含专科手术。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2876","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"筛检试验中，阳性预测值是指","options":["筛检阴性者中无病的比例","患病者被筛出的比例","筛检阳性者中真正患病的比例","筛检人数中患病人数"],"answer":2,"explanation":"阳性预测值=真阳性/(真阳性+假阳性)，反映筛检阳性者中真正患病的概率。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2877","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国法定传染病报告实行","options":["电话口头报告","逐级邮寄上报","网络直报制度","自愿报告"],"answer":2,"explanation":"法定传染病通过传染病监测信息系统网络直报，责任报告人须按时限报告。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2878","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"突发公共卫生事件报告的时限要求是","options":["48小时内","24小时内","12小时内","2小时内向属地卫生行政部门报告"],"answer":3,"explanation":"较大以上突发公共卫生事件须在2小时内报告，随后进行进程报告。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2879","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国基本医疗卫生与健康促进法》规定，我国医疗卫生事业应当坚持","options":["公益性原则","营利性原则","市场化原则","自由化原则"],"answer":0,"explanation":"医疗卫生事业坚持公益性原则。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2880","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国卫生法律体系的核心法律是","options":["《医疗机构管理条例》","《执业医师法》","《中华人民共和国基本医疗卫生与健康促进法》","《药品管理法》"],"answer":2,"explanation":"基本医疗卫生与健康促进法为卫生健康领域基础性、综合性法律。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2881","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师经注册后，可以在医疗卫生机构中","options":["按照注册的执业地点、执业类别、执业范围执业","随意执业","跨类别执业","无限制执业"],"answer":0,"explanation":"医师应按注册的执业地点、类别和范围执业。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2882","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医师法》规定，医师注册后变更执业地点等事项应","options":["无需变更","办理变更注册手续","重新考试","注销执业"],"answer":1,"explanation":"医师变更执业地点、类别、范围等应办理变更注册。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2883","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师在执业活动中应履行的义务不包括","options":["宣传健康知识","遵守法律法规","保护患者隐私","获取工资报酬"],"answer":3,"explanation":"获取报酬为医师权利，非义务。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2884","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师在执业活动中享有的权利不包括","options":["接受培训","获得报酬","遵守诊疗规范","提出意见建议"],"answer":2,"explanation":"遵守诊疗规范为义务，非权利。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2885","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师实施医疗、预防、保健措施，签署有关医学证明文件，必须","options":["随意签署","凭经验签署","由他人代签","亲自诊查、调查"],"answer":3,"explanation":"医师签署医学证明文件须亲自诊查、调查，不得伪造、篡改。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2886","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师不得出具与自己执业范围无关或者与执业类别不相符的医学证明文件，这一规定属于","options":["执业保障","执业权利","执业义务","执业规则"],"answer":3,"explanation":"此为医师执业规则中的禁止性规定。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2887","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"未经医师亲自诊查，医疗机构不得出具","options":["收费单","疾病诊断书、健康证明书等医学证明文件","处方","病历"],"answer":1,"explanation":"未经亲自诊查不得出具疾病诊断书、健康证明书、死亡证明书等。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2888","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师发现传染病疫情时，应当按照规定","options":["及时向所在机构报告","隐瞒不报","仅告知家属","自行处理"],"answer":0,"explanation":"医师发现疫情应按规定及时报告，不得隐瞒、缓报、谎报。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2889","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师对急危患者应当采取紧急措施进行诊治，","options":["不得拒绝急救处置","可拒绝","可延迟","可转诊后处理"],"answer":0,"explanation":"对急危患者，医师应采取紧急措施，不得拒绝急救处置。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2890","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"执业医师资格考试的条件不包括","options":["具有医学专业学历","在医疗机构试用期满一年","通过考试","年满18周岁"],"answer":0,"explanation":"报考条件包括学历、试用期等，18周岁非法定条件。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2891","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构执业必须进行","options":["工商登记","登记并取得《医疗机构执业许可证》","税务登记","无需许可"],"answer":1,"explanation":"医疗机构执业须登记取得执业许可证，按核准范围执业。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2892","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构不得因就诊者是传染病病人而","options":["上报疫情","正常治疗","隔离治疗","拒绝治疗或歧视"],"answer":3,"explanation":"医疗机构不得拒绝治疗或歧视传染病病人。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2893","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构施行手术、特殊检查或特殊治疗时，必须征得","options":["患者同意，并取得其家属或关系人签字（紧急情况除外）","仅医生同意","仅护士同意","无需同意"],"answer":0,"explanation":"手术、特殊治疗须征得患者同意并签字；不能签字时由家属或关系人同意并签字。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2894","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗事故的构成要件不包括","options":["患者主观不满意","医疗机构及其医务人员","违反医疗卫生法规","过失造成患者人身损害"],"answer":0,"explanation":"医疗事故构成要件包括主体、违法性、过失、人身损害及因果关系，患者主观不满意非要件。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2895","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗事故分为","options":["二级","三级","五级","四级"],"answer":3,"explanation":"医疗事故分四级：一级（死亡、重度残疾）、二级、三级、四级。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2896","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"造成患者死亡或重度残疾的医疗事故属于","options":["二级","一级医疗事故","三级","四级"],"answer":1,"explanation":"一级医疗事故指造成患者死亡、重度残疾。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2897","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发生医疗事故争议时，病历资料应","options":["由医院单方保管","在医患双方在场情况下封存","由患者保管","销毁"],"answer":1,"explanation":"病历应医患双方在场封存，由医疗机构保管。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2898","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者有权复印的病历资料不包括","options":["住院志","门诊病历","主观病历（病例讨论记录）","检验报告"],"answer":2,"explanation":"患者可复印客观病历；主观病历（讨论记录等）不可复印但可封存。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2899","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗事故技术鉴定由","options":["法院组织","医学会组织","卫生行政部门直接鉴定","医院自行鉴定"],"answer":1,"explanation":"医疗事故技术鉴定由医学会组织专家鉴定组进行。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2900","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医疗事故处理条例》规定，医疗事故赔偿争议的解决途径不包括","options":["刑事拘留","行政调解","民事诉讼","自行协商"],"answer":3,"explanation":"解决途径为协商、行政调解、民事诉讼，无刑事拘留。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2901","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国传染病防治法》规定，传染病防治的方针是","options":["预防为主、防治结合、分类管理","治疗为主","隔离为主","消毒为主"],"answer":0,"explanation":"传染病防治实行预防为主、防治结合、分类管理的方针。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2902","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"传染病病人、病原携带者和疑似传染病病人，在治愈前或者在排除传染病嫌疑前，不得从事","options":["任何工作","法律禁止的易使该传染病扩散的工作","轻体力工作","居家活动"],"answer":1,"explanation":"不得从事法律禁止的易使传染病扩散的工作（如餐饮、托幼等）。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2903","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构发现甲类传染病时，应当及时采取的措施不包括","options":["对密切接触者医学观察","对病人予以隔离治疗","对疑似病人隔离治疗前指定场所隔离","对疑似病人进行居家隔离"],"answer":3,"explanation":"甲类传染病疑似病人应在指定场所单独隔离治疗，非居家隔离。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2904","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构对本单位内被传染病病原体污染的场所、物品以及医疗废物，应","options":["堆放","随意处理","出售","实施消毒处理"],"answer":3,"explanation":"应按规定消毒处理，医疗废物按《医疗废物管理条例》处置。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2905","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗废物分为","options":["三类","五类","四类","六类"],"answer":1,"explanation":"医疗废物分感染性、损伤性、病理性、药物性、化学性五类。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2906","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗废物暂时贮存的时间不得超过","options":["1天","2天","3天","7天"],"answer":1,"explanation":"医疗废物暂时贮存不超过2天，由有资质单位集中处置。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2907","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国药品管理法》规定，药品生产必须","options":["税务登记","工商登记","取得药品生产许可证","无需许可"],"answer":2,"explanation":"药品生产须取得药品生产许可证，符合GMP要求。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2908","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药品不良反应是指","options":["合格药品在正常用法用量下出现的与用药目的无关的有害反应","假药反应","过量反应","过敏反应"],"answer":0,"explanation":"药品不良反应定义强调合格药品、正常用法用量。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2909","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药品不良反应报告的原则是","options":["确诊后报","可疑即报","严重后报","不报"],"answer":1,"explanation":"药品不良反应实行可疑即报原则。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2910","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"国家实行药品不良反应报告制度，医疗机构发现药品不良反应应","options":["按规定报告","隐瞒","仅告知患者","自行处理"],"answer":0,"explanation":"医疗机构应按规定及时报告药品不良反应。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2911","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"处方管理办法规定，处方应由","options":["护士开具","取得处方权的医师开具","药师开具","患者自行开具"],"answer":1,"explanation":"处方由取得处方权的执业医师开具，药师审核调配。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2912","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"处方一般不得超过","options":["30日用量","3日用量","15日用量","7日用量"],"answer":3,"explanation":"处方一般不超过7日用量，急诊处方不超过3日用量。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2913","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"麻醉药品和第一类精神药品处方不得超过","options":["7日用量","3日用量","1日用量","15日用量"],"answer":2,"explanation":"麻醉药品和第一类精神药品处方不超过1日用量（门诊）。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2914","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"第二类精神药品处方一般不得超过","options":["3日用量","1日用量","7日用量","15日用量"],"answer":2,"explanation":"第二类精神药品处方一般不超过7日用量。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2915","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构应当对麻醉药品处方进行","options":["销毁","随意处理","保存1年","专册登记，保存3年"],"answer":3,"explanation":"麻醉药品处方保存3年，精神药品处方保存2年，普通处方保存1年。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2916","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国献血法》规定，国家提倡","options":["强制献血","十八周岁至五十五周岁的健康公民自愿献血","有偿献血","儿童献血"],"answer":1,"explanation":"献血法提倡18～55周岁健康公民自愿献血。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2917","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"血站采集血液必须","options":["仅登记","随意采集","不检查","进行健康检查"],"answer":3,"explanation":"血站对献血者必须免费进行必要的健康检查。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2918","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构临床用血应当","options":["随意用血","制定用血计划，合理用血","大量用血","不用血"],"answer":1,"explanation":"临床用血应合理、节约，推行成分输血。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2919","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国母婴保健法》规定，婚前医学检查包括","options":["严重遗传性疾病、指定传染病、有关精神病","所有疾病","仅体检","仅化验"],"answer":0,"explanation":"婚前医学检查针对严重遗传病、指定传染病和有关精神病。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2920","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"母婴保健技术服务的内容不包括","options":["孕产期保健","婚前保健","器官移植","新生儿疾病筛查"],"answer":2,"explanation":"母婴保健技术服务包括婚前、孕产期、婴幼儿保健等，不含器官移植。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2921","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医疗机构管理条例》规定，医疗机构必须将《医疗机构执业许可证》、诊疗科目、诊疗时间和收费标准","options":["不公示","保密","存档","悬挂于明显处"],"answer":3,"explanation":"医疗机构应将执业许可证等悬挂于明显处，接受监督。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2922","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构工作人员上岗时，必须","options":["佩戴载有本人姓名、职务或职称的标牌","不佩戴","随意着装","不挂牌"],"answer":0,"explanation":"工作人员应佩戴标牌，便于患者识别。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2923","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国医务人员医德规范》的核心是","options":["个人利益","经济效益","救死扶伤，实行社会主义人道主义","单位利益"],"answer":2,"explanation":"医德规范核心为救死扶伤、防病治病，实行社会主义人道主义，全心全意为人民健康服务。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2924","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医德规范中，对医务人员的基本要求是","options":["尊重患者的人格与权利","服从领导","完成指标","维护单位"],"answer":0,"explanation":"医德规范要求尊重患者人格与权利，不分民族、性别、职业、地位，一视同仁。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2925","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学的基本原则是","options":["效益、效率","自主、保密","公平、公开","尊重、不伤害、有利、公正"],"answer":3,"explanation":"医学伦理四原则：尊重（自主）、不伤害、有利（行善）、公正。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2926","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学中，尊重原则的核心是","options":["尊重患者的人格和自主权","服从患者","患者至上","医生决定"],"answer":0,"explanation":"尊重原则要求尊重患者人格、自主决定权及隐私。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2927","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"知情同意的主体是","options":["家属","具有完全民事行为能力的患者本人","医生","单位"],"answer":1,"explanation":"知情同意由患者本人决定；无民事行为能力者由法定代理人代行。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2928","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者知情同意权的内容不包括","options":["决定治疗方案由医生全权负责","了解病情","了解治疗方案","了解医疗费用"],"answer":3,"explanation":"患者有权了解病情、方案、费用并自主选择，医生不能全权代替患者决定。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2929","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗保密的内容不包括","options":["为医院保密","为患者保密","向无关人员泄露患者隐私","为同事保密"],"answer":2,"explanation":"医疗保密要求不向无关人员泄露患者隐私及诊疗信息。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2930","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学中，公正原则是指","options":["公平、合理地分配卫生资源","平均分配","按需分配","按地位分配"],"answer":0,"explanation":"公正原则包括资源分配公正和人际交往公正。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2931","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学中，不伤害原则是指","options":["避免使患者受到不应有的伤害","不治疗","不手术","不检查"],"answer":0,"explanation":"不伤害原则要求避免可避免的伤害，权衡利弊。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2932","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学中，有利原则是指","options":["社会利益","医院利益","医生利益","把患者利益放在首位，促进其健康"],"answer":3,"explanation":"有利原则要求医务人员的行为对患者有利，促进健康。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2933","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临床诊疗伦理原则不包括","options":["知情同意原则","整体化原则","最优化原则","利益最大化原则"],"answer":1,"explanation":"临床诊疗伦理原则包括整体化、最优化、知情同意、协同一致等，不含利益最大化。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2934","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临床诊疗中的最优化原则是指","options":["最快方案","最贵方案","以最小代价获得最佳诊疗效果","最新方案"],"answer":2,"explanation":"最优化原则要求疗效最佳、安全、痛苦少、费用低。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2935","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"人体器官捐献应遵循的原则是","options":["强制","有偿","自愿、无偿","随意"],"answer":2,"explanation":"人体器官捐献遵循自愿、无偿原则，禁止买卖器官。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2936","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"人体器官移植应遵循的原则不包括","options":["伦理审查","买卖器官","知情同意","非商业"],"answer":1,"explanation":"器官移植须伦理审查、知情同意，禁止商业买卖。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2937","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"涉及人的生物医学研究应遵循的原则不包括","options":["以科学利益为重","知情同意","保护受试者","伦理审查"],"answer":0,"explanation":"研究应以受试者健康利益为重，非科学利益优先。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2938","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"伦理委员会的职责不包括","options":["审查研究方案","批准研究经费","保护受试者权益","监督研究过程"],"answer":1,"explanation":"伦理委员会审查研究方案、保护受试者，不负责经费审批。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2939","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学研究中的知情同意书应包括","options":["仅受益","仅研究目的","仅风险","研究目的、方法、风险、受益及自愿退出权利"],"answer":3,"explanation":"知情同意书应全面告知研究信息，保障受试者权益。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2940","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者自主选择权的含义是","options":["患者有权选择医疗机构、医生及诊疗方案","患者决定一切","医生决定","家属决定"],"answer":0,"explanation":"患者自主选择权包括选择医疗机构、医生、诊疗方案等。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2941","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"保护患者隐私权的措施不包括","options":["保密病历","遮挡诊疗环境","公开患者病情","限制无关人员"],"answer":2,"explanation":"保护隐私应遮挡环境、保密病历，不得公开病情。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2942","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学人文关怀的核心是","options":["以医院为中心","以疾病为中心","以医生为中心","以患者为中心，尊重生命"],"answer":3,"explanation":"医学人文关怀强调以患者为中心，尊重生命价值。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2943","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患关系的模式中，最理想的是","options":["共同参与型","主动-被动型","指导-合作型","命令型"],"answer":0,"explanation":"医患关系三种模式中，共同参与型最理想，体现平等合作。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2944","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患沟通的基本原则不包括","options":["单向告知","尊重","真诚","有效"],"answer":0,"explanation":"医患沟通应双向、尊重、真诚、有效，非单向告知。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2945","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患沟通中，医生应","options":["打断患者","倾听患者诉求，耐心解释","敷衍","回避"],"answer":1,"explanation":"医患沟通应倾听、共情、耐心解释，建立信任。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2946","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗纠纷预防的措施不包括","options":["完善病历","规范诊疗","有效沟通","隐瞒病情"],"answer":3,"explanation":"预防医疗纠纷应规范诊疗、有效沟通、完善病历，不得隐瞒病情。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2947","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医疗纠纷预防和处理条例》规定，发生医疗纠纷后，患者可选择的途径不包括","options":["协商","聚众闹事","人民调解","诉讼"],"answer":1,"explanation":"医疗纠纷解决途径为协商、人民调解、行政调解、诉讼，不得聚众闹事。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2948","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病历书写的基本要求不包括","options":["规范","客观、真实、准确","及时、完整","主观臆造"],"answer":3,"explanation":"病历书写应客观、真实、准确、及时、完整、规范，不得臆造。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2949","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病历书写中，抢救记录应在抢救结束后","options":["48小时内","24小时内","12小时内","6小时内据实补记"],"answer":3,"explanation":"抢救结束后6小时内据实补记抢救记录。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2950","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"手术记录应由","options":["护士书写","术者书写","家属书写","患者书写"],"answer":1,"explanation":"手术记录由术者在术后24小时内完成。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2951","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国医师法》施行的时间是","options":["2022年3月1日","1999年5月1日","2020年1月1日","2021年1月1日"],"answer":0,"explanation":"《医师法》于2022年3月1日施行，取代原《执业医师法》。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2952","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医师法》规定，医师应当坚持","options":["经济效益为中心","人民健康为中心","个人发展为中心","单位利益为中心"],"answer":1,"explanation":"医师应坚持人民健康为中心，履行防病治病、救死扶伤的职责。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2953","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师应当遵循的临床诊疗指南是","options":["个人经验","国家发布的诊疗指南和临床路径","网络资料","民间偏方"],"answer":1,"explanation":"医师应遵循国家发布的诊疗指南、临床路径和技术操作规范。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2954","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师在诊疗活动中应当使用","options":["自制药","随意药品","过期药品","经依法批准并按规定开具的药品和医疗器械"],"answer":3,"explanation":"医师应使用经批准的药品和器械，按规定开具。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2955","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师不得利用职务之便","options":["正常休息","正常收费","正常诊疗","索要、收受财物或不正当利益"],"answer":3,"explanation":"医师不得索要、收受患者财物或不正当利益。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2956","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"违反《医师法》规定，医师造成医疗事故的，应承担的法律责任不包括","options":["民事责任","行政责任","刑事责任","道德谴责"],"answer":2,"explanation":"法律责任包括行政、民事、刑事责任，道德谴责非法律责任。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2957","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学心理学的研究对象是","options":["心理因素与健康和疾病的相互关系","仅疾病","仅药物","仅手术"],"answer":0,"explanation":"医学心理学研究心理社会因素在健康与疾病中的作用及相互关系。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2958","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学模式的发展经历了","options":["神灵主义、自然哲学、机械论、生物医学、生物-心理-社会医学模式","仅生物医学模式","仅心理模式","无变化"],"answer":0,"explanation":"医学模式从神灵主义到生物-心理-社会医学模式不断演进。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2959","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"现代医学模式是","options":["生物医学模式","生物-心理-社会医学模式","自然哲学模式","机械论模式"],"answer":1,"explanation":"1977年恩格尔提出生物-心理-社会医学模式。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2960","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心理评估的常用方法不包括","options":["体格检查","观察法","会谈法","心理测验法"],"answer":0,"explanation":"心理评估常用观察、会谈、心理测验等，体格检查非心理评估方法。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2961","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心理测验按功能分类不包括","options":["智力测验","人格测验","神经心理测验","血常规检查"],"answer":0,"explanation":"心理测验按功能分智力、人格、神经心理等测验，血常规非心理测验。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2962","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"常用的智力测验量表是","options":["明尼苏达多相人格调查表","艾森克人格问卷","SCL-90","韦氏智力量表"],"answer":3,"explanation":"韦氏智力量表（WAIS）为常用智力测验；艾森克、明尼苏达为人格测验。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2963","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"常用的自评症状量表是","options":["SCL-90（症状自评量表）","韦氏量表","比奈量表","瑞文测验"],"answer":0,"explanation":"SCL-90为常用精神症状自评量表。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2964","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心理治疗的主要方法不包括","options":["精神分析","药物治疗","行为治疗","认知治疗"],"answer":1,"explanation":"心理治疗包括精神分析、行为、认知、人本主义等，药物治疗非心理治疗。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2965","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"行为治疗的理论基础是","options":["精神分析理论","条件反射理论","人本主义理论","认知理论"],"answer":1,"explanation":"行为治疗以经典条件反射和操作性条件反射为理论基础。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2966","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"系统脱敏疗法适用于","options":["精神分裂症","恐惧症","器质性疾病","昏迷"],"answer":1,"explanation":"系统脱敏用于恐惧、焦虑等，通过逐步暴露减轻反应。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2967","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"认知治疗的核心是","options":["改变不合理认知","改变行为","改变环境","改变药物"],"answer":0,"explanation":"认知治疗通过识别和改变不合理认知改善情绪和行为。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2968","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者角色的适应不良类型不包括","options":["角色行为缺如","角色行为增强","角色行为冲突","角色行为消退"],"answer":1,"explanation":"患者角色适应不良包括缺如、冲突、减退、强化、异常等，无“增强”类型。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2969","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者角色行为强化是指","options":["拒绝承认患病","安于患者角色，不愿恢复","隐瞒病情","积极配合"],"answer":1,"explanation":"角色强化指患者安于角色、依赖性增强，不愿恢复社会角色。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2970","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患关系的基本模式不包括","options":["主动-被动型","指导-合作型","共同参与型","对立-冲突型"],"answer":0,"explanation":"医患关系三种模式：主动-被动、指导-合作、共同参与，无对立-冲突型。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2971","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"共同参与型医患关系适用于","options":["休克患者","昏迷患者","婴幼儿","慢性病且有一定文化水平的患者"],"answer":3,"explanation":"共同参与型适用于慢性病、有自主能力的患者。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2972","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患沟通中，非语言沟通不包括","options":["姿势","表情","书面通知","眼神"],"answer":2,"explanation":"非语言沟通包括表情、姿势、眼神、触摸等，书面通知为语言沟通。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2973","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医务人员的心理素质要求不包括","options":["耐心","情绪稳定","情绪不稳定","同理心"],"answer":2,"explanation":"医务人员应情绪稳定、耐心、有同理心，情绪不稳定为不良素质。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2974","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"共情是指","options":["说教","同情","怜悯","设身处地理解患者感受"],"answer":3,"explanation":"共情（同理心）指设身处地理解并回应患者感受。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2975","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临终关怀的理念是","options":["加速死亡","延长生命","提高临终患者生命质量，减轻痛苦","放弃治疗"],"answer":2,"explanation":"临终关怀以提高生命质量、减轻痛苦、维护尊严为目标。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2976","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学人文精神的核心是","options":["技术至上","追求经济效益","尊重人的生命价值","效率优先"],"answer":2,"explanation":"医学人文精神强调尊重生命、以人为本。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2977","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"RNA转录的方向是？","options":["3'→5'","5'→3'","双向进行","随机方向"],"answer":1,"explanation":"RNA聚合酶沿模板3'→5'移动，产物按5'→3'延伸。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-2978","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"原核生物RNA聚合酶中识别启动子的是？","options":["α亚基","σ因子","β亚基","ρ因子"],"answer":1,"explanation":"σ因子识别并结合启动子，起始转录。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2979","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"真核生物mRNA前体的加工不包括？","options":["5'端加帽","与核糖体结合","3'端加polyA尾","剪接内含子"],"answer":1,"explanation":"mRNA加工包括加帽、加尾、剪接；与核糖体结合发生在胞质翻译阶段。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2980","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"DNA复制与RNA转录共有的特点是？","options":["都以双链DNA全部为模板","都需要引物","都按5'→3'方向合成","产物相同"],"answer":2,"explanation":"复制和转录均沿5'→3'合成；转录不需引物且只转录模板链。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2981","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"不对称转录的含义是？","options":["只以双链DNA中的一条链为模板转录","两条链同时对称转录","转录产物不对称","转录速度不均匀"],"answer":0,"explanation":"基因组中每个基因只转录模板链（反义链），称不对称转录。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2982","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"蛋白质合成的直接模板是？","options":["mRNA","DNA","tRNA","rRNA"],"answer":0,"explanation":"mRNA上的密码子决定氨基酸序列，是翻译的直接模板。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-2983","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"蛋白质生物合成的起始密码子是？","options":["UAG","UAA","AUG","UGA"],"answer":2,"explanation":"AUG编码甲硫氨酸并作为起始密码；UAA、UAG、UGA为终止密码。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-2984","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肽链合成的方向是？","options":["随机方向","从C端向N端","双向进行","从N端向C端"],"answer":3,"explanation":"核糖体沿mRNA移动，肽链由N端向C端延伸。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-2985","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氨基酸的活化由哪种酶催化？","options":["转氨酶","转肽酶","氨基酰-tRNA合成酶","氨基酸脱羧酶"],"answer":2,"explanation":"氨基酰-tRNA合成酶催化氨基酸与tRNA结合并耗能。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2986","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"终止密码子的作用是？","options":["起始翻译","编码稀有氨基酸","终止肽链合成并释放多肽","调节翻译速度"],"answer":2,"explanation":"终止密码无对应氨基酸，由释放因子识别终止翻译。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2987","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"属于抑癌基因的是？","options":["myc","ras","p53","src"],"answer":2,"explanation":"p53、Rb为经典抑癌基因；ras、myc、src为癌基因。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2988","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"原癌基因激活的方式不包括？","options":["抑癌基因表达增强","点突变","基因扩增","染色体易位"],"answer":0,"explanation":"原癌基因经突变、扩增、易位等激活；抑癌基因失活与激活癌基因是两类事件。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2989","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"基因表达调控中最重要的环节是？","options":["翻译后修饰","转录水平的调控","蛋白质降解","mRNA降解"],"answer":1,"explanation":"基因表达以转录水平调控最为关键、最经济。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2990","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"反转录（逆转录）是指？","options":["以RNA为模板合成RNA","以DNA为模板合成RNA","以RNA为模板合成DNA","以DNA为模板合成蛋白质"],"answer":2,"explanation":"反转录酶以RNA为模板合成互补DNA（cDNA）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2991","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"生物转化中结合反应最常见的结合物是？","options":["乙酰基","硫酸","葡萄糖醛酸","甲基"],"answer":2,"explanation":"第二相结合反应以与葡萄糖醛酸结合最普遍。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2992","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肝生物转化的特点不包括？","options":["绝对解毒，产物均无毒","反应连续性","多样性与双重性（解毒或致毒）","酶系多样"],"answer":0,"explanation":"生物转化后多数毒性降低，但少数产物毒性反而增强。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-2993","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"胆汁酸合成的原料是？","options":["脂肪酸","胆红素","磷脂","胆固醇"],"answer":3,"explanation":"肝细胞以胆固醇为原料合成胆汁酸，是胆固醇的主要去路。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-2994","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"游离胆红素（间接胆红素）的特点是？","options":["与葡萄糖醛酸结合","水溶性高","可直接经肾排出","脂溶性高，不能经肾排出"],"answer":3,"explanation":"游离胆红素与清蛋白结合运输，脂溶性高，不能经肾排泄。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2995","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"溶血性黄疸的胆红素变化特点是？","options":["血结合胆红素明显升高","血间接胆红素明显升高","尿胆红素强阳性","粪胆素原减少"],"answer":1,"explanation":"溶血使游离胆红素生成增多，间接胆红素升高，尿胆红素阴性。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2996","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"正常人血清中含量最多的血浆蛋白是？","options":["γ球蛋白","α球蛋白","β球蛋白","清蛋白"],"answer":3,"explanation":"清蛋白占血浆蛋白总量约一半以上，主要维持血浆胶体渗透压。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-2997","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"体内含量最多的阳离子（细胞外液）是？","options":["K⁺","Na⁺","Ca²⁺","Mg²⁺"],"answer":1,"explanation":"细胞外液以Na⁺为主；细胞内液以K⁺为主。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-2998","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"血浆中最重要的缓冲系统是？","options":["蛋白质缓冲系统","磷酸盐缓冲系统","血红蛋白缓冲系统","碳酸氢盐缓冲系统"],"answer":3,"explanation":"NaHCO₃/H₂CO₃缓冲能力强、量大，是血浆最重要的缓冲系统。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-2999","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"调节钙磷代谢最重要的激素组合是？","options":["PTH、活性维生素D和降钙素","胰岛素和胰高血糖素","甲状腺激素和肾上腺素","醛固酮和抗利尿激素"],"answer":0,"explanation":"PTH升钙磷、活性VitD促肠钙吸收、降钙素降血钙，共同调节钙磷。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-3000","_shard":"qk-yiliao-05"}]);